package com.codex.gearroadmap;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CodexGearRoadmapPluginRunner
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CodexGearRoadmapPlugin.class);
		RuneLite.main(args);
	}
}

package com.codex.gearroadmap;

import com.codex.gearroadmap.core.Fighter;
import com.codex.gearroadmap.core.SlayerTask;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(CodexGearRoadmapConfig.GROUP)
public interface CodexGearRoadmapConfig extends Config
{
	String GROUP = "codexgearroadmap";
	String TARGET = "target";
	String SLAYER_TASK = "slayerTask";
	/** The old on-task switch, read once to carry a "never" choice over to the slayer task setting. */
	String OLD_ON_TASK = "onTask";

	@ConfigSection(
		name = "Fighting",
		description = "What Gear Roadmap assumes about how you fight",
		position = 0
	)
	String fighting = "fighting";

	@ConfigSection(
		name = "Claimed upgrades",
		description = "What Gear Roadmap does when you get an upgrade on your road",
		position = 1
	)
	String claims = "claims";

	@ConfigItem(
		keyName = TARGET,
		name = "Target",
		description = "The monster the roadmap is for. Pick one from the Targets tab in the panel",
		position = 0,
		section = fighting
	)
	default String target()
	{
		return "Vorkath";
	}

	@ConfigItem(
		keyName = "boost",
		name = "Potions",
		description = "Which boosting potions to assume you drink",
		position = 1,
		section = fighting
	)
	default Fighter.Boost boost()
	{
		return Fighter.Boost.POTIONS;
	}

	@ConfigItem(
		keyName = "prayers",
		name = "Offensive prayers",
		description = "Assume you pray the best offensive prayer you have unlocked",
		position = 2,
		section = fighting
	)
	default boolean prayers()
	{
		return true;
	}

	@ConfigItem(
		keyName = SLAYER_TASK,
		name = "Slayer helmet bonus",
		description = "When to count the black mask and slayer helmet bonus. By default it counts against Slayer"
			+ " monsters, and against a boss only while your current task covers it",
		position = 3,
		section = fighting
	)
	default SlayerTask.Mode slayerTask()
	{
		return SlayerTask.Mode.SMART;
	}

	@ConfigItem(
		keyName = "showPlaque",
		name = "Show plaque",
		description = "Show a plaque in the game view when you get an upgrade from your road",
		position = 1,
		section = claims
	)
	default boolean showPlaque()
	{
		return true;
	}

	@Range(min = 3, max = 30)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "plaqueSeconds",
		name = "Plaque time",
		description = "How long the plaque stays up",
		position = 2,
		section = claims
	)
	default int plaqueSeconds()
	{
		return 8;
	}

	@ConfigItem(
		keyName = "chatLine",
		name = "Upgrade in chat",
		description = "Add a line to the chat box with the damage a claimed upgrade adds",
		position = 3,
		section = claims
	)
	default boolean chatLine()
	{
		return true;
	}
}

package com.codex.gearroadmap;

import com.codex.gearroadmap.core.Advisor;
import com.codex.gearroadmap.core.Fighter;
import com.codex.gearroadmap.core.Report;
import com.codex.gearroadmap.core.Roadmap;
import com.codex.gearroadmap.core.SlayerTask;
import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.RoadmapData;
import com.codex.gearroadmap.data.Target;
import com.codex.gearroadmap.overlay.UpgradePlaque;
import com.codex.gearroadmap.ui.Format;
import com.codex.gearroadmap.ui.GearRoadmapPanel;
import com.codex.gearroadmap.ui.ItemIcons;
import com.codex.gearroadmap.ui.Sigil;
import com.codex.gearroadmap.ui.Theme;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.inject.Provides;
import java.io.IOException;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicInteger;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.AsyncBufferedImage;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Codex Gear Roadmap",
	description = "Ranks your next gear upgrades by damage gained per coin against the monster you are aiming at",
	tags = {"gear", "upgrade", "dps", "damage", "bis", "best", "loadout", "money", "codex"}
)
public class CodexGearRoadmapPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CodexGearRoadmapPlugin.class);
	private static final String BANK_KEY = "bank";
	private static final Skill[] SKILLS = {
		Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.MAGIC, Skill.PRAYER, Skill.HITPOINTS, Skill.AGILITY,
	};
	private static final Set<Integer> UNLOCK_VARBITS = new HashSet<>(Arrays.asList(
		VarbitID.PRAYER_RIGOUR_UNLOCKED, VarbitID.PRAYER_AUGURY_UNLOCKED, VarbitID.KR_KNIGHTWAVES_STATE,
		VarbitID.PRAYER_DEADEYE_UNLOCKED, VarbitID.PRAYER_MYSTIC_VIGOUR_UNLOCKED, VarbitID.KANDARIN_DIARY_HARD_COMPLETE,
		VarbitID.IRONMAN));
	private static final Set<Integer> TASK_VARPS = new HashSet<>(Arrays.asList(VarPlayerID.SLAYER_COUNT, VarPlayerID.SLAYER_TARGET));
	/** The slayer task id that stands for "a boss", whose name is then looked up from the boss id. */
	private static final int BOSS_TASK = 98;
	/** King's Ransom's knight training is done from this state on, which unlocks Piety and Chivalry. */
	private static final int KNIGHT_WAVES_DONE = 8;
	private static final int ANALYSE_GAP_TICKS = 3;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	@Inject
	private CodexGearRoadmapConfig config;

	private final UpgradePlaque plaque = new UpgradePlaque();
	private final AtomicInteger generation = new AtomicInteger();
	private final Set<String> claimed = new HashSet<>();

	private RoadmapData data;
	private Advisor advisor;
	private Set<Integer> priceIds = Collections.emptySet();
	private GearRoadmapPanel panel;
	private NavigationButton navButton;

	private String profile;
	private Set<Integer> worn = Collections.emptySet();
	private Set<Integer> inventory = Collections.emptySet();
	private Bank bank;
	private long inventoryCoins;
	private Boolean ancients;
	private boolean dirty;
	private boolean coinsDirty;
	private int ticksSinceAnalysis;
	private final Map<Skill, Integer> realLevels = new HashMap<>();
	/** Which task the plan was made for; the kill count falls on every kill and must not re-plan each time. */
	private String taskKey;
	/** The analysis whose report was last published, so a coin update never lands on a road about to be replaced. */
	private volatile int publishedTicket;

	/** What the latest roadmap was, so a claimed upgrade can be named; written on the executor. */
	private volatile Roadmap lastRoadmap;
	private volatile Report lastReport;
	private volatile String lastName;
	private volatile SurveyCache survey;

	/** The bank as last seen, saved per account so the roadmap knows it between sessions. */
	static final class Bank
	{
		Set<Integer> items = new TreeSet<>();
		long coins;
	}

	private static final class SurveyCache
	{
		final String key;
		final List<Roadmap.Survey> rows;

		SurveyCache(String key, List<Roadmap.Survey> rows)
		{
			this.key = key;
			this.rows = rows;
		}
	}

	@Provides
	CodexGearRoadmapConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexGearRoadmapConfig.class);
	}

	@Override
	protected void startUp() throws IOException
	{
		migrateConfig();
		data = RoadmapData.load(gson);
		advisor = new Advisor(data);
		priceIds = advisor.priceIds();
		ItemIcons icons = (itemId, onLoaded) ->
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(onLoaded);
			return image;
		};
		panel = new GearRoadmapPanel(icons, name -> configManager.setConfiguration(CodexGearRoadmapConfig.GROUP,
			CodexGearRoadmapConfig.TARGET, name));
		navButton = NavigationButton.builder()
			.tooltip("Codex Gear Roadmap")
			.icon(Sigil.icon(16))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(plaque);
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loadBank();
				readContainer(InventoryID.WORN);
				readContainer(InventoryID.INV);
				dirty = true;
			}
		});
	}

	/** The old on-task switch becomes the slayer task setting; only an explicit "off" needs carrying over. */
	private void migrateConfig()
	{
		String old = configManager.getConfiguration(CodexGearRoadmapConfig.GROUP, CodexGearRoadmapConfig.OLD_ON_TASK);
		if (old == null)
		{
			return;
		}
		if ("false".equals(old)
			&& configManager.getConfiguration(CodexGearRoadmapConfig.GROUP, CodexGearRoadmapConfig.SLAYER_TASK) == null)
		{
			configManager.setConfiguration(CodexGearRoadmapConfig.GROUP, CodexGearRoadmapConfig.SLAYER_TASK, SlayerTask.Mode.NEVER);
		}
		configManager.unsetConfiguration(CodexGearRoadmapConfig.GROUP, CodexGearRoadmapConfig.OLD_ON_TASK);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(plaque);
		clientToolbar.removeNavigation(navButton);
		plaque.clear();
		generation.incrementAndGet();
		clientThread.invokeLater(this::forget);
		panel = null;
	}

	private void forget()
	{
		profile = null;
		bank = null;
		worn = Collections.emptySet();
		inventory = Collections.emptySet();
		inventoryCoins = 0;
		ancients = null;
		lastRoadmap = null;
		lastReport = null;
		realLevels.clear();
		taskKey = null;
		survey = null;
		claimed.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			forget();
			plaque.clear();
			generation.incrementAndGet();
			publish(Report.loggedOut(), null);
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		bank = null;
		profile = null;
		ancients = null;
		survey = null;
		claimed.clear();
		loadBank();
		dirty = true;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CodexGearRoadmapConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (!config.showPlaque())
		{
			plaque.clear();
		}
		dirty = true;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id != InventoryID.WORN && id != InventoryID.INV && id != InventoryID.BANK)
		{
			return;
		}
		// The first sight of the bank is not a claim: everything in it was simply unknown before.
		boolean bankKnown = bank != null;
		Set<Integer> before = ownedIds();
		long coinsBefore = coins();
		readContainer(id);
		Set<Integer> after = ownedIds();
		if (!after.equals(before))
		{
			dirty = true;
			if (bankKnown)
			{
				checkClaims(before, after);
			}
		}
		else if (coins() != coinsBefore)
		{
			// Coins only move the "in reach" line, which does not need a new plan.
			coinsDirty = true;
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		// Experience drops fire this on every hit; only a new real level changes the plan.
		for (Skill skill : SKILLS)
		{
			if (skill == event.getSkill())
			{
				Integer previous = realLevels.put(skill, event.getLevel());
				if (previous == null || previous != event.getLevel())
				{
					dirty = true;
				}
				return;
			}
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (UNLOCK_VARBITS.contains(event.getVarbitId()))
		{
			dirty = true;
		}
		else if (event.getVarbitId() == VarbitID.SLAYER_TARGET_BOSSID
			|| event.getVarbitId() == -1 && TASK_VARPS.contains(event.getVarpId()))
		{
			// Only a new task, or the end of one, changes the plan; the count itself does not.
			boolean onTask = client.getVarpValue(VarPlayerID.SLAYER_COUNT) > 0;
			String key = onTask ? client.getVarpValue(VarPlayerID.SLAYER_TARGET) + ":"
				+ client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID) : "";
			if (!key.equals(taskKey))
			{
				taskKey = key;
				dirty = true;
			}
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		// Switching to another RuneLite profile does not restart the plugin, so that profile's old setting is carried over here.
		migrateConfig();
		dirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (profile == null)
		{
			loadBank();
		}
		ticksSinceAnalysis++;
		if (dirty && ticksSinceAnalysis >= ANALYSE_GAP_TICKS)
		{
			dirty = false;
			coinsDirty = false;
			ticksSinceAnalysis = 0;
			analyse();
		}
		else if (coinsDirty && !dirty && publishedTicket == generation.get())
		{
			coinsDirty = false;
			Report report = lastReport;
			if (report != null && report.getRoadmap() != null)
			{
				Report recoined = report.withRoadmap(report.getRoadmap().withCoins(report.isIronman() ? 0 : coins()));
				lastReport = recoined;
				lastRoadmap = recoined.getRoadmap();
				publish(recoined, lastName);
			}
		}
	}

	private void readContainer(int id)
	{
		ItemContainer container = client.getItemContainer(id);
		if (container == null)
		{
			return;
		}
		Set<Integer> items = new TreeSet<>();
		for (Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0 && data.gear(item.getId()) != null)
			{
				items.add(item.getId());
			}
		}
		if (id == InventoryID.WORN)
		{
			worn = items;
		}
		else if (id == InventoryID.INV)
		{
			inventory = items;
			inventoryCoins = coinsIn(container);
		}
		else
		{
			Bank seen = new Bank();
			seen.items = items;
			seen.coins = coinsIn(container);
			if (bank == null || !bank.items.equals(seen.items) || bank.coins != seen.coins)
			{
				bank = seen;
				saveBank();
			}
		}
	}

	/** Coins and platinum tokens, each token worth a thousand. */
	private static long coinsIn(ItemContainer container)
	{
		return container.count(ItemID.COINS) + 1000L * container.count(ItemID.PLATINUM);
	}

	private Set<Integer> ownedIds()
	{
		Set<Integer> ids = new HashSet<>(worn);
		ids.addAll(inventory);
		if (bank != null)
		{
			ids.addAll(bank.items);
		}
		return ids;
	}

	private long coins()
	{
		return inventoryCoins + (bank == null ? 0 : bank.coins);
	}

	private void loadBank()
	{
		String key = configManager.getRSProfileKey();
		if (key == null)
		{
			return;
		}
		profile = key;
		String json = configManager.getRSProfileConfiguration(CodexGearRoadmapConfig.GROUP, BANK_KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}
		try
		{
			Bank saved = gson.fromJson(json, Bank.class);
			if (saved != null && saved.items != null)
			{
				bank = saved;
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Could not read the saved bank, waiting to see it again", e);
		}
	}

	private void saveBank()
	{
		if (profile == null)
		{
			profile = configManager.getRSProfileKey();
		}
		if (profile != null && bank != null)
		{
			configManager.setConfiguration(CodexGearRoadmapConfig.GROUP, profile, BANK_KEY, gson.toJson(bank));
		}
	}

	/** Names the upgrades from the road the player just picked up. */
	private void checkClaims(Set<Integer> before, Set<Integer> after)
	{
		Roadmap map = lastRoadmap;
		if (map == null)
		{
			return;
		}
		List<Roadmap.Step> path = map.getPath();
		for (int i = 0; i < path.size(); i++)
		{
			Roadmap.Option option = path.get(i).getOption();
			if (claimed.contains(option.getName()) || !ownsAll(option.getPieces(), after) || ownsAll(option.getPieces(), before))
			{
				continue;
			}
			claimed.add(option.getName());
			announce(map, i, option);
		}
	}

	private static boolean ownsAll(List<Gear> pieces, Set<Integer> ids)
	{
		for (Gear piece : pieces)
		{
			boolean has = false;
			for (int id : piece.getIds())
			{
				if (ids.contains(id))
				{
					has = true;
					break;
				}
			}
			if (!has)
			{
				return false;
			}
		}
		return true;
	}

	private void announce(Roadmap map, int index, Roadmap.Option option)
	{
		String target = map.getTarget().getName();
		String gain = Format.gain(option.getGain()) + " DPS against " + target;
		List<Roadmap.Step> path = map.getPath();
		String next = index + 1 < path.size()
			? "Next: " + path.get(index + 1).getOption().getName() + ", " + Format.coins(path.get(index + 1).getOption().getCost())
			: "That was the last stop on this road";
		if (config.showPlaque())
		{
			plaque.show(new UpgradePlaque.View("UPGRADE CLAIMED", option.getName(), gain, next, Theme.GOLD,
				itemManager.getImage(option.getIcon().getId()), System.currentTimeMillis(), config.plaqueSeconds() * 1000L));
		}
		if (config.chatLine())
		{
			String line = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Gear Roadmap: ")
				.append(ChatColorType.NORMAL).append(option.getName() + " adds ")
				.append(ChatColorType.HIGHLIGHT).append(Format.gain(option.getGain()) + " DPS")
				.append(ChatColorType.NORMAL).append(" against " + target + ".")
				.build();
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(line)
				.build());
		}
	}

	private Fighter fighter()
	{
		Map<String, Integer> levels = new HashMap<>();
		for (Skill skill : SKILLS)
		{
			levels.put(skill.getName(), client.getRealSkillLevel(skill));
		}
		if (ancients == null)
		{
			ancients = Quest.DESERT_TREASURE_I.getState(client) == QuestState.FINISHED;
		}
		boolean piety = client.getVarbitValue(VarbitID.KR_KNIGHTWAVES_STATE) >= KNIGHT_WAVES_DONE;
		boolean rigour = client.getVarbitValue(VarbitID.PRAYER_RIGOUR_UNLOCKED) == 1;
		boolean augury = client.getVarbitValue(VarbitID.PRAYER_AUGURY_UNLOCKED) == 1;
		boolean deadeye = client.getVarbitValue(VarbitID.PRAYER_DEADEYE_UNLOCKED) == 1;
		boolean vigour = client.getVarbitValue(VarbitID.PRAYER_MYSTIC_VIGOUR_UNLOCKED) == 1;
		boolean kandarin = client.getVarbitValue(VarbitID.KANDARIN_DIARY_HARD_COMPLETE) == 1;
		SlayerTask task = SlayerTask.of(config.slayerTask(), currentTask());
		return new Fighter(levels, config.boost(), config.prayers(), piety, rigour, augury, ancients, task)
			.withUnlocks(deadeye, vigour, kandarin);
	}

	/** The name of the player's current slayer task, as the slayer helper shows it, or null. */
	private String currentTask()
	{
		if (client.getVarpValue(VarPlayerID.SLAYER_COUNT) <= 0)
		{
			return null;
		}
		try
		{
			int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
			int row;
			if (taskId == BOSS_TASK)
			{
				List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID,
					DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
				if (rows.isEmpty())
				{
					return null;
				}
				row = (Integer) client.getDBTableField(rows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
			}
			else
			{
				List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
				if (rows.isEmpty())
				{
					return null;
				}
				row = rows.get(0);
			}
			return (String) client.getDBTableField(row, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
		}
		catch (RuntimeException e)
		{
			log.debug("Could not read the slayer task", e);
			return null;
		}
	}

	private void analyse()
	{
		Set<Integer> ids = ownedIds();
		Set<Gear> owned = new LinkedHashSet<>();
		for (int id : ids)
		{
			Gear g = data.gear(id);
			if (g != null)
			{
				owned.add(g);
			}
		}
		Fighter fighter = fighter();
		Map<Integer, Long> prices = new HashMap<>();
		for (int id : priceIds)
		{
			long price = itemManager.getItemPrice(id);
			if (price > 0)
			{
				prices.put(id, price);
			}
		}
		Target target = data.target(config.target());
		if (target == null)
		{
			target = data.targets().get(0);
		}
		boolean ironman = client.getVarbitValue(VarbitID.IRONMAN) > 0;
		// Ironmen cannot buy, so their coins never put an upgrade in reach.
		long coins = ironman ? 0 : coins();
		boolean bankSeen = bank != null;
		boolean seasonal = client.getWorldType().contains(WorldType.SEASONAL);
		String boosts = config.boost().toString();
		String task = fighter.getTask().getTask();
		Boolean slayer = target.isSlayer() ? fighter.onTaskFor(target) : null;
		String surveyKey = new TreeSet<>(ids) + "|" + fighter.getLevels() + "|" + fighter.assumptions() + unlocks();
		Player player = client.getLocalPlayer();
		String name = player == null ? null : player.getName();
		Target aim = target;
		int ticket = generation.incrementAndGet();
		executor.execute(() ->
		{
			try
			{
				Roadmap map = advisor.plan(owned, fighter, aim, id -> prices.getOrDefault(id, 0L), coins);
				SurveyCache cached = survey;
				if (cached == null || !cached.key.equals(surveyKey))
				{
					cached = new SurveyCache(surveyKey, advisor.survey(owned, fighter));
				}
				if (ticket == generation.get())
				{
					survey = cached;
					lastRoadmap = map;
					Report report = new Report(true, map, cached.rows, boosts, owned.size(), bankSeen)
						.withAccount(ironman, seasonal, task, slayer);
					lastReport = report;
					lastName = name;
					publishedTicket = ticket;
					publish(report, name);
				}
			}
			catch (RuntimeException e)
			{
				log.warn("Gear Roadmap planning failed", e);
			}
		});
	}

	private String unlocks()
	{
		return client.getVarbitValue(VarbitID.KR_KNIGHTWAVES_STATE) + "/" + client.getVarbitValue(VarbitID.PRAYER_RIGOUR_UNLOCKED)
			+ "/" + client.getVarbitValue(VarbitID.PRAYER_AUGURY_UNLOCKED);
	}

	private void publish(Report report, String name)
	{
		GearRoadmapPanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(report, name));
		}
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.CatalogueEntry;
import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.RoadmapData;
import com.codex.gearroadmap.data.Target;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Weighs every upgrade in the catalogue against the player's best loadout for one target,
 * then walks the road ahead: the upgrade with the most damage per coin first, then the
 * next one from there, and so on. Earned upgrades and ones the player cannot wield yet
 * are listed on their own.
 */
public final class Advisor
{
	public static final int STEPS = 8;
	public static final int AMMO_STACK = 1000;
	private static final int SIDE_LIST = 4;
	/** How many of the cheapest do-nothing-alone pieces the road tries in pairs. */
	private static final int PAIR_POOL = 10;

	/** Grand Exchange prices: 0 when an item has none. */
	public interface Prices
	{
		long price(int itemId);
	}

	private static final String[][] BUNDLES = {
		{"Void melee set", "Pest Control", "void melee helm", "void knight top", "void knight robe", "void knight gloves"},
		{"Void ranger set", "Pest Control", "void ranger helm", "void knight top", "void knight robe", "void knight gloves"},
		{"Void mage set", "Pest Control", "void mage helm", "void knight top", "void knight robe", "void knight gloves"},
		{"Elite void ranger set", "Pest Control and the Western Provinces hard diary", "void ranger helm", "elite void top", "elite void robe", "void knight gloves"},
		{"Elite void mage set", "Pest Control and the Western Provinces hard diary", "void mage helm", "elite void top", "elite void robe", "void knight gloves"},
		{"Obsidian armour", null, "obsidian helmet", "obsidian platebody", "obsidian platelegs"},
	};

	/** Earned upgrades that are pointless once a better form of the same item is owned. */
	private static final String[][] SUPERSEDED = {
		{"salve amulet", "salve amulet(i)", "salve amulet (e)", "salve amulet(ei)"},
		{"salve amulet(i)", "salve amulet (e)", "salve amulet(ei)"},
		{"salve amulet (e)", "salve amulet(ei)"},
		{"black mask", "black mask (i)", "slayer helmet", "slayer helmet (i)"},
		{"black mask (i)", "slayer helmet (i)"},
		{"slayer helmet", "slayer helmet (i)"},
		{"fire cape", "infernal cape"},
		{"ava's accumulator", "ava's assembler", "dizana's quiver", "blessed dizana's quiver"},
		{"saradomin cape", "imbued saradomin cape"},
	};

	private final RoadmapData data;
	private final Planner planner;

	public Advisor(RoadmapData data)
	{
		this.data = data;
		this.planner = new Planner(data);
	}

	public Planner planner()
	{
		return planner;
	}

	/** The roadmap for one target. */
	public Roadmap plan(Collection<Gear> ownedGear, Fighter fighter, Target target, Prices prices, long coins)
	{
		Set<Gear> owned = new LinkedHashSet<>(ownedGear);
		Planner.Best start = planner.optimise(owned, fighter, target);
		double base = start.dps();
		List<Candidate> candidates = candidates(owned);

		List<Roadmap.Option> free = new ArrayList<>();
		List<Roadmap.Option> locked = new ArrayList<>();
		List<Roadmap.Option> bought = new ArrayList<>();
		Map<Roadmap.Option, Integer> shortBy = new HashMap<>();
		for (Candidate c : candidates)
		{
			long cost = cost(c, owned, prices);
			if (cost < 0)
			{
				continue;
			}
			Planner.Plan after = planner.withAdded(start, owned, c.pieces, fighter, target);
			double gain = after.dps() - base;
			if (gain < threshold(base))
			{
				continue;
			}
			String missing = fighter.missing(c.requirements);
			Roadmap.Option option = new Roadmap.Option(c.name, c.pieces, c.icon(), cost, gain, base, after, missing,
				c.earn, cost == 0 && c.earn == null ? imbueNote(c) : c.note, c.ammo);
			if (missing != null)
			{
				locked.add(option);
				shortBy.put(option, fighter.shortfall(c.requirements));
			}
			else if (cost == 0)
			{
				free.add(option);
			}
			else
			{
				bought.add(option);
			}
		}
		Comparator<Roadmap.Option> byGain = Comparator.comparingDouble((Roadmap.Option o) -> -o.getGain());
		free.sort(byGain);
		// One reward of the same task in one slot is enough: the dragon gloves need not stand
		// beside the barrows gloves that the same quest gives later.
		Set<String> rewards = new HashSet<>();
		free.removeIf(o -> o.getEarn() != null && !rewards.add(o.getEarn() + "/" + o.getIcon().getSlot()));
		// What a few more levels unlock comes before a dream forty levels away.
		locked.sort(Comparator.comparingDouble((Roadmap.Option o) -> -o.getGain() / (1 + shortBy.get(o) / 10.0)));

		List<Roadmap.Step> path = walk(owned, fighter, target, prices, coins, start, candidates);
		Set<String> onPath = new HashSet<>();
		for (Roadmap.Step step : path)
		{
			onPath.add(step.getOption().getName());
		}
		List<Roadmap.Option> leaps = new ArrayList<>();
		bought.sort(byGain);
		for (Roadmap.Option o : bought)
		{
			if (!onPath.contains(o.getName()) && leaps.size() < SIDE_LIST)
			{
				leaps.add(o);
			}
		}
		return new Roadmap(target, start, path, cut(free, SIDE_LIST + 2), cut(locked, SIDE_LIST), leaps, coins);
	}

	/** Greedy road: the best damage per coin, then again from the gear that leaves. */
	private List<Roadmap.Step> walk(Set<Gear> owned, Fighter fighter, Target target, Prices prices, long coins,
		Planner.Best start, List<Candidate> candidates)
	{
		Set<Gear> have = new LinkedHashSet<>(owned);
		Planner.Best current = start;
		List<Roadmap.Step> path = new ArrayList<>();
		long spent = 0;
		Set<Candidate> used = new HashSet<>();
		for (int step = 0; step < STEPS; step++)
		{
			double base = current.dps();
			Candidate pick = null;
			Planner.Plan pickPlan = null;
			long pickCost = 0;
			double pickRatio = 0;
			List<Candidate> pickParts = Collections.emptyList();
			List<Candidate> flat = new ArrayList<>();
			Map<Candidate, Long> flatCost = new HashMap<>();
			for (Candidate c : candidates)
			{
				if (used.contains(c) || have.containsAll(c.pieces) || fighter.missing(c.requirements) != null)
				{
					continue;
				}
				long cost = cost(c, have, prices);
				if (cost <= 0)
				{
					continue;
				}
				Planner.Plan after = planner.withAdded(current, have, c.pieces, fighter, target);
				double gain = after.dps() - base;
				if (gain < threshold(base))
				{
					if (c.pieces.size() == 1 && !c.ammo && morePower(c.pieces.get(0), current.best()))
					{
						flat.add(c);
						flatCost.put(c, cost);
					}
					continue;
				}
				double ratio = gain / cost;
				if (ratio > pickRatio)
				{
					pick = c;
					pickPlan = after;
					pickCost = cost;
					pickRatio = ratio;
				}
			}
			// A piece that adds strength or accuracy short of the next max hit does nothing alone,
			// yet two of them together can cross it: try the cheapest such pieces in pairs.
			flat.sort(Comparator.comparingLong(flatCost::get));
			int pool = Math.min(flat.size(), PAIR_POOL);
			for (int i = 0; i < pool; i++)
			{
				for (int j = i + 1; j < pool; j++)
				{
					Candidate a = flat.get(i);
					Candidate b = flat.get(j);
					if (a.pieces.get(0).getSlot() == b.pieces.get(0).getSlot())
					{
						continue;
					}
					long cost = flatCost.get(a) + flatCost.get(b);
					List<Gear> both = new ArrayList<>(a.pieces);
					both.addAll(b.pieces);
					Planner.Plan after = planner.withAdded(current, have, both, fighter, target);
					double gain = after.dps() - base;
					if (gain >= threshold(base) && gain / cost > pickRatio)
					{
						pick = new Candidate(a.name + " + " + b.name, both, a.requirements, null, null, false);
						pickPlan = after;
						pickCost = cost;
						pickRatio = gain / cost;
						pickParts = Arrays.asList(a, b);
					}
				}
			}
			if (pick == null)
			{
				break;
			}
			used.add(pick);
			used.addAll(pickParts);
			have.addAll(pick.pieces);
			Planner.Best next = planner.optimise(have, fighter, target);
			// The fresh search is never worse than the quick one; keep whichever found more.
			Planner.Plan plan = next.dps() >= pickPlan.dps() ? next.best() : pickPlan;
			spent += pickCost;
			Roadmap.Option option = new Roadmap.Option(pick.name, pick.pieces, pick.icon(), pickCost, plan.dps() - base, base, plan,
				null, null, pick.note, pick.ammo);
			path.add(new Roadmap.Step(option, spent, spent <= coins));
			current = next;
		}
		return path;
	}

	/** Every item id the roadmap may price, so the plugin can look them up on the client thread. */
	public Set<Integer> priceIds()
	{
		Set<Integer> ids = new HashSet<>();
		for (Candidate c : candidates(Collections.emptySet()))
		{
			for (Gear piece : c.pieces)
			{
				for (int id : piece.getIds())
				{
					ids.add(id);
				}
				CatalogueEntry entry = data.entry(piece);
				if (entry != null && entry.getBuild() != null)
				{
					for (int id : entry.getBuild())
					{
						ids.add(id);
					}
				}
			}
		}
		return ids;
	}

	/** Every target's best loadout, for the Targets tab. */
	public List<Roadmap.Survey> survey(Collection<Gear> owned, Fighter fighter)
	{
		List<Roadmap.Survey> rows = new ArrayList<>();
		for (Target t : data.targets())
		{
			Planner.Best best = planner.optimise(owned, fighter, t);
			rows.add(new Roadmap.Survey(t, best.best()));
		}
		return rows;
	}

	/** Whether a piece has more damage than what the plan wears in its slot, for the plan's own style. */
	static boolean morePower(Gear g, Planner.Plan plan)
	{
		Result.Kind kind = plan.getResult().getKind();
		if (kind == null || g.getSlot() == Gear.WEAPON)
		{
			return false;
		}
		Gear worn = plan.getLoadout().get(g.getSlot());
		return power(g, kind) > (worn == null ? 0 : power(worn, kind));
	}

	private static int power(Gear g, Result.Kind kind)
	{
		switch (kind)
		{
			case RANGED:
				return g.rangedStrength();
			case MAGIC:
				return g.magicDamage();
			default:
				return g.strength();
		}
	}

	private static double threshold(double base)
	{
		return Math.max(0.02, base * 0.004);
	}

	private static <T> List<T> cut(List<T> list, int size)
	{
		return list.size() <= size ? list : new ArrayList<>(list.subList(0, size));
	}

	private static String imbueNote(Candidate c)
	{
		return c.note == null ? "Made from gear you own" : c.note + ", which you own";
	}

	/** Coins to buy what is not owned yet: -1 when something has no price. */
	long cost(Candidate c, Set<Gear> owned, Prices prices)
	{
		if (c.earn != null)
		{
			return 0;
		}
		long total = 0;
		for (Gear piece : c.pieces)
		{
			if (owned.contains(piece))
			{
				continue;
			}
			CatalogueEntry entry = data.entry(piece);
			int[] build = entry == null ? null : entry.getBuild();
			if (build != null)
			{
				for (int id : build)
				{
					Gear part = data.gear(id);
					if (part != null && owned.contains(part))
					{
						continue;
					}
					long p = prices.price(id);
					if (p <= 0)
					{
						return -1;
					}
					total += p;
				}
				continue;
			}
			long cheapest = -1;
			for (int id : piece.getIds())
			{
				long p = prices.price(id);
				if (p > 0 && (cheapest < 0 || p < cheapest))
				{
					cheapest = p;
				}
			}
			if (cheapest < 0)
			{
				return -1;
			}
			total += cheapest * (piece.getSlot() == Gear.AMMO ? AMMO_STACK : 1);
		}
		return total;
	}

	List<Candidate> candidates(Set<Gear> owned)
	{
		List<Candidate> list = new ArrayList<>();
		for (CatalogueEntry entry : data.catalogue())
		{
			Gear g = entry.getGear();
			if (owned.contains(g) || g.getName().startsWith("Void ") || g.getName().startsWith("Elite void")
				|| g.key().startsWith("obsidian helmet") || superseded(g, owned))
			{
				continue;
			}
			list.add(new Candidate(g.getName(), Collections.singletonList(g), entry.getRequirements(), entry.getEarn(),
				entry.getNote(), g.getSlot() == Gear.AMMO));
		}
		for (String[] bundle : BUNDLES)
		{
			List<Gear> pieces = new ArrayList<>();
			Map<String, Integer> req = new HashMap<>();
			for (int i = 2; i < bundle.length; i++)
			{
				Gear g = data.named(bundle[i]);
				if (g == null)
				{
					pieces = null;
					break;
				}
				pieces.add(g);
				CatalogueEntry entry = data.entry(g);
				if (entry != null)
				{
					entry.getRequirements().forEach((k, v) -> req.merge(k, v, Math::max));
				}
			}
			if (pieces != null && !owned.containsAll(pieces))
			{
				list.add(new Candidate(bundle[0], pieces, req, bundle[1], null, false));
			}
		}
		return list;
	}

	private boolean superseded(Gear g, Set<Gear> owned)
	{
		for (String[] row : SUPERSEDED)
		{
			if (!row[0].equals(g.key()))
			{
				continue;
			}
			for (int i = 1; i < row.length; i++)
			{
				Gear better = data.named(row[i]);
				if (better != null && owned.contains(better))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Something the roadmap can recommend: one piece, or a set that only works whole. */
	static final class Candidate
	{
		final String name;
		final List<Gear> pieces;
		final Map<String, Integer> requirements;
		final String earn;
		final String note;
		final boolean ammo;

		Candidate(String name, List<Gear> pieces, Map<String, Integer> requirements, String earn, String note, boolean ammo)
		{
			this.name = name;
			this.pieces = pieces;
			this.requirements = requirements;
			this.earn = earn;
			this.note = note;
			this.ammo = ammo;
		}

		/** The piece whose picture stands for it: a set shows its body. */
		Gear icon()
		{
			for (Gear g : pieces)
			{
				if (g.getSlot() == Gear.BODY)
				{
					return g;
				}
			}
			return pieces.get(0);
		}
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.RoadmapData;
import com.codex.gearroadmap.data.Target;
import java.util.Set;

/**
 * The game's combat formulas for one loadout against one monster: effective levels,
 * attack and defence rolls, max hits, and the special effects that change them, such
 * as the salve amulet, slayer helmet, void, crystal armour, the twisted bow and the
 * dragon and demon bane weapons. Every style the weapon offers is tried and the
 * fastest one is kept.
 */
public final class Calc
{
	private static final double TICK = 0.6;

	private static final String[][] STANDARD_SPELLS = {
		{"Fire Strike", "13", "8"}, {"Fire Bolt", "35", "12"}, {"Fire Blast", "59", "16"},
		{"Fire Wave", "75", "20"}, {"Fire Surge", "95", "24"},
	};
	private static final String[][] ANCIENT_SPELLS = {
		{"Ice Rush", "58", "16"}, {"Ice Burst", "70", "22"}, {"Ice Blitz", "82", "26"}, {"Ice Barrage", "94", "30"},
	};

	/** The staves that can autocast the Ancient Magicks, by the start of their names. */
	private static final String[] ANCIENT_STAVES = {
		"ancient staff", "ahrim's staff", "master wand", "kodai wand", "nightmare staff", "harmonised nightmare staff",
		"eldritch nightmare staff", "volatile nightmare staff", "staff of the dead", "toxic staff of the dead",
		"staff of light", "staff of balance", "zuriel's staff", "void knight mace", "blue moon spear",
	};
	/** The soulreaper axe is assumed to be kept at its full stacks. */
	static final int SOULREAPER_STACKS = 5;

	private final RoadmapData data;

	public Calc(RoadmapData data)
	{
		this.data = data;
	}

	/** The best result over every style the weapon offers. */
	public Result best(Loadout loadout, Fighter fighter, Target target)
	{
		return best(loadout, fighter, target, null);
	}

	/** The best result using only one kind of attack, or any when kind is null. */
	public Result best(Loadout loadout, Fighter fighter, Target target, Result.Kind kind)
	{
		return evaluate(loadout, fighter, target, kind, null, null);
	}

	/** One attack type and stance, such as "stab" and "Aggressive", as the equipment screen would set it. */
	public Result styled(Loadout loadout, Fighter fighter, Target target, String type, String stance)
	{
		return evaluate(loadout, fighter, target, null, type, stance);
	}

	private Result evaluate(Loadout loadout, Fighter fighter, Target target, Result.Kind kind, String onlyType, String onlyStance)
	{
		Gear weapon = loadout.weapon();
		String category = weapon == null ? "Unarmed" : weapon.getCategory();
		Totals totals = new Totals(loadout, data.ammoFor(weapon));
		Result best = Result.NONE;
		for (RoadmapData.Style style : data.styles(category))
		{
			String type = style.getType();
			String stance = style.getStance();
			if (stance == null || stance.startsWith("Defensive") || "Longrange".equals(stance) && !"magic".equals(type)
				|| onlyType != null && !(onlyType.equals(type) && onlyStance.equals(stance)))
			{
				continue;
			}
			Result.Kind styleKind = "magic".equals(type) ? Result.Kind.MAGIC : "ranged".equals(type) ? Result.Kind.RANGED : Result.Kind.MELEE;
			if (!target.allows(styleKind.name()))
			{
				continue;
			}
			Result r;
			if ("magic".equals(type))
			{
				if (kind != null && kind != Result.Kind.MAGIC)
				{
					continue;
				}
				r = "Autocast".equals(stance) ? autocast(loadout, totals, fighter, target) : powered(loadout, totals, fighter, target, stance);
			}
			else if ("ranged".equals(type))
			{
				if (kind != null && kind != Result.Kind.RANGED)
				{
					continue;
				}
				r = ranged(loadout, totals, fighter, target, stance);
			}
			else
			{
				if (kind != null && kind != Result.Kind.MELEE)
				{
					continue;
				}
				r = melee(loadout, totals, fighter, target, type, stance);
			}
			if (r.isBetterThan(best))
			{
				best = r;
			}
		}
		return best;
	}

	/** Summed bonuses, leaving out ammunition the weapon does not fire. */
	static final class Totals
	{
		final int[] offence = new int[5];
		int strength;
		int rangedStrength;
		int magicDamage;
		boolean ammoValid = true;
		/** Whether the weapon fires the ammunition worn, as bows and crossbows do. */
		boolean firesAmmo;

		Totals(Loadout loadout, Set<Integer> fires)
		{
			Gear ammo = loadout.get(Gear.AMMO);
			boolean countAmmo = fires != null && !fires.isEmpty();
			if (countAmmo)
			{
				ammoValid = ammo != null && firesAny(fires, ammo);
				firesAmmo = ammoValid;
			}
			for (int slot = 0; slot < Gear.SLOTS; slot++)
			{
				Gear g = loadout.get(slot);
				if (g == null)
				{
					continue;
				}
				boolean projectileIgnored = slot == Gear.AMMO && !countAmmo;
				for (int t = 0; t < 5; t++)
				{
					if (!(projectileIgnored && t == Gear.RANGED))
					{
						offence[t] += g.offence(t);
					}
				}
				strength += g.strength();
				if (!projectileIgnored)
				{
					rangedStrength += g.rangedStrength();
				}
				magicDamage += g.magicDamage();
			}
		}

		private static boolean firesAny(Set<Integer> fires, Gear ammo)
		{
			for (int id : ammo.getIds())
			{
				if (fires.contains(id))
				{
					return true;
				}
			}
			return false;
		}
	}

	private Result melee(Loadout lo, Totals tot, Fighter f, Target t, String type, String stance)
	{
		int attackType = "stab".equals(type) ? Gear.STAB : "slash".equals(type) ? Gear.SLASH : Gear.CRUSH;
		Gear weapon = lo.weapon();
		String key = weapon == null ? "" : weapon.key();
		Fighter.Prayer prayer = f.meleePrayer();
		int effAttack = f.attack() * prayer.accuracy / 100 + 8 + ("Accurate".equals(stance) ? 3 : "Controlled".equals(stance) ? 1 : 0);
		int strengthLevel = f.strength() * prayer.strength / 100;
		if (key.equals("soulreaper axe"))
		{
			// Kept at its full five stacks, each worth 6% of the strength level; it does not stack with prayers.
			strengthLevel += f.strength() * SOULREAPER_STACKS * 6 / 100;
		}
		int effStrength = strengthLevel + 8 + ("Aggressive".equals(stance) ? 3 : "Controlled".equals(stance) ? 1 : 0);
		if (voidSet(lo, "void melee helm", false))
		{
			effAttack = effAttack * 11 / 10;
			effStrength = effStrength * 11 / 10;
		}
		long baseRoll = (long) effAttack * (tot.offence[attackType] + 64);
		int baseMax = (effStrength * (tot.strength + 64) + 320) / 640;
		long roll = baseRoll;
		int max = baseMax;

		// The salve amulet and the black mask do not stack; the salve wins on undead.
		boolean undead = t.is("undead");
		boolean demon = t.is("demon");
		boolean dragon = t.is("dragon");
		boolean kalphite = t.is("kalphite");
		boolean revenant = revenantBonus(lo, t, "ursine chainmace", "viggora's chainmace");
		if (undead && lo.wearsAny("salve amulet (e)", "salve amulet(ei)"))
		{
			roll = roll * 6 / 5;
			max = max * 6 / 5;
		}
		else if (undead && lo.wearsAny("salve amulet", "salve amulet(i)"))
		{
			roll = roll * 7 / 6;
			max = max * 7 / 6;
		}
		else if (slayerBonus(lo, f, t, false))
		{
			roll = roll * 7 / 6;
			max = max * 7 / 6;
		}

		// Accuracy, in the order the game applies it.
		boolean obsidian = tzhaarWeapon(lo) && lo.wears("obsidian helmet") && lo.wears("obsidian platebody") && lo.wears("obsidian platelegs");
		if (obsidian)
		{
			roll += baseRoll / 10;
		}
		if (revenant)
		{
			roll = roll * 3 / 2;
		}
		int bane = !demon ? 0 : lo.wearsAny("arclight", "emberlight") ? 70 : lo.wearsAny("silverlight", "darklight") ? 60 : 0;
		bane = bane * t.demonbaneVulnerability() / 100;
		roll += roll * bane / 100;
		if (dragon && key.equals("dragon hunter lance"))
		{
			roll = roll * 6 / 5;
		}
		if (kalphite && key.equals("keris partisan of breaching"))
		{
			roll = roll * 133 / 100;
		}
		int inquisitor = attackType != Gear.CRUSH ? 0 : (lo.wears("inquisitor's great helm") ? 1 : 0)
			+ (lo.wears("inquisitor's hauberk") ? 2 : 0) + (lo.wears("inquisitor's plateskirt") ? 2 : 0);
		roll = roll * (200 + inquisitor) / 200;

		// Max hit, in the order the game applies it.
		if (demon && lo.wearsAny("arclight", "emberlight"))
		{
			max += max * bane / 100;
		}
		if (obsidian)
		{
			max += baseMax / 10;
		}
		if (dragon && key.equals("dragon hunter lance"))
		{
			max = max * 6 / 5;
		}
		if (kalphite && key.startsWith("keris"))
		{
			max = max * (key.equals("keris partisan of amascut") ? 115 : 133) / 100;
		}
		if (revenant)
		{
			max = max * 3 / 2;
		}
		if (demon && lo.wearsAny("silverlight", "darklight"))
		{
			max += max * bane / 100;
		}
		if (key.equals("colossal blade"))
		{
			max += Math.min(t.getSize() * 2, 10);
		}
		max = max * (200 + inquisitor) / 200;

		long defence = (long) (t.getDefence() + 9) * (t.defensive(attackType) + 64);
		boolean fang = key.startsWith("osmumten's fang");
		// The fang rolls its accuracy twice only when it stabs.
		double accuracy = fang && attackType == Gear.STAB ? fangChance(roll, defence) : hitChance(roll, defence);
		boolean berserker = tzhaarWeapon(lo) && lo.wears("berserker necklace");
		boolean shieldBreaker = lo.wearsAny("arclight", "emberlight", "silverlight", "darklight") || key.startsWith("abyssal");
		// Spears, hastas and halberds stab the Corporeal Beast in full, as does the fang.
		boolean corpbane = attackType == Gear.STAB && (fang || key.endsWith("halberd") || key.contains("hasta")
			|| key.contains("spear") && !key.equals("blue moon spear"));
		Npc npc = new Npc(t, Result.Kind.MELEE, shieldBreaker, corpbane);
		double damage;
		if (fang)
		{
			// The fang never rolls in the bottom or top 15% of its range.
			int low = max * 3 / 20;
			max -= low;
			damage = accuracy * npc.mean(low, max, 1, 1, 0);
		}
		else if (key.contains("of vitur"))
		{
			// The scythe's second and third swings hit large monsters for half and a quarter, each rolled on its own.
			damage = 0;
			for (int i = 0; i < Math.min(3, t.getSize()); i++)
			{
				damage += accuracy * npc.mean(0, max >> i, 1, 1, 0);
			}
		}
		else if (key.equals("dual macuahuitl"))
		{
			// Two half hits; the second is only thrown when the first lands.
			int first = max / 2;
			damage = accuracy * npc.mean(0, first, 1, 1, 0) + accuracy * accuracy * npc.mean(0, max - first, 1, 1, 0);
		}
		else if (berserker)
		{
			damage = accuracy * npc.mean(0, max, 6, 5, 0);
			max = max * 6 / 5;
		}
		else if (kalphite && key.startsWith("keris"))
		{
			// One hit in 51 deals triple damage.
			damage = accuracy * (npc.mean(0, max, 1, 1, 0) * 50 + npc.mean(0, max, 3, 1, 0)) / 51;
		}
		else
		{
			damage = accuracy * npc.mean(0, max, 1, 1, 0);
		}
		int ticks = speed(weapon);
		String label = capital(type) + ", " + stance.toLowerCase();
		return new Result(Result.Kind.MELEE, damage / (ticks * TICK), max, accuracy, ticks, label, prayer.name, null);
	}

	private Result ranged(Loadout lo, Totals tot, Fighter f, Target t, String stance)
	{
		if (!tot.ammoValid)
		{
			return Result.NONE;
		}
		Gear weapon = lo.weapon();
		String key = weapon == null ? "" : weapon.key();
		Fighter.Prayer prayer = f.rangedPrayer();
		int effAttack = f.ranged() * prayer.accuracy / 100 + 8 + ("Accurate".equals(stance) ? 3 : 0);
		int effStrength = f.ranged() * prayer.strength / 100 + 8 + ("Accurate".equals(stance) ? 3 : 0);
		if (voidSet(lo, "void ranger helm", false))
		{
			effAttack = effAttack * 11 / 10;
			effStrength = voidSet(lo, "void ranger helm", true) ? effStrength * 9 / 8 : effStrength * 11 / 10;
		}
		int bonus = tot.offence[Gear.RANGED];
		int strength = tot.rangedStrength;
		if (key.startsWith("toxic blowpipe"))
		{
			// Loaded with dragon darts.
			strength += 35;
		}
		if (tot.firesAmmo && lo.wearsAny("dizana's quiver", "blessed dizana's quiver", "dizana's max cape"))
		{
			// A charged quiver adds to arrows and bolts the weapon fires.
			bonus += 10;
			strength += 1;
		}
		long roll = (long) effAttack * (bonus + 64);
		int max = (effStrength * (strength + 64) + 320) / 640;

		boolean crystal = key.startsWith("crystal bow") || key.startsWith("bow of faerdhinen");
		int pieces = !crystal ? 0 : (lo.wears("crystal helm") ? 1 : 0) + (lo.wears("crystal legs") ? 2 : 0) + (lo.wears("crystal body") ? 3 : 0);
		roll = roll * (20 + pieces) / 20;
		max = max * (40 + pieces) / 40;

		boolean undead = t.is("undead");
		boolean dragonbane = t.is("dragon") && key.equals("dragon hunter crossbow");
		boolean demonbane = t.is("demon") && key.equals("scorching bow");
		boolean revenant = revenantBonus(lo, t, "webweaver bow", "craw's bow");
		boolean salve = undead && lo.wearsAny("salve amulet(ei)", "salve amulet(i)");
		boolean mask = !salve && slayerBonus(lo, f, t, true);
		if (salve)
		{
			int num = lo.wears("salve amulet(ei)") ? 6 : 7;
			roll = roll * num / (num - 1);
		}
		else if (mask)
		{
			roll = roll * 23 / 20;
		}
		if (key.equals("twisted bow"))
		{
			int magic = Math.min(250, Math.max(t.getMagic(), t.getMagicAttack()));
			roll = twistedBow(roll, magic, true);
		}
		if (revenant)
		{
			roll = roll * 3 / 2;
		}
		if (dragonbane)
		{
			roll = roll * 13 / 10;
		}
		int bane = 30 * t.demonbaneVulnerability() / 100;
		if (demonbane)
		{
			roll += roll * bane / 100;
		}

		if (salve)
		{
			int num = lo.wears("salve amulet(ei)") ? 6 : 7;
			max = max * num / (num - 1);
		}
		else if (mask)
		{
			// The imbued slayer helmet adds to the revenant, dragon and demon bonuses rather than multiplying them.
			int numerator = 23 + (revenant ? 10 : 0) + (dragonbane ? 5 : 0) + (demonbane ? 6 : 0);
			max = max * numerator / 20;
			revenant = false;
			dragonbane = false;
			demonbane = false;
		}
		if (key.equals("twisted bow"))
		{
			int magic = Math.min(250, Math.max(t.getMagic(), t.getMagicAttack()));
			max = (int) twistedBow(max, magic, false);
		}
		if (revenant)
		{
			max = max * 3 / 2;
		}
		if (dragonbane)
		{
			max = max * 5 / 4;
		}
		if (demonbane)
		{
			max += max * bane / 100;
		}

		String category = weapon == null ? "" : weapon.getCategory();
		int defType = "Thrown".equals(category) ? Target.D_LIGHT : "Bow".equals(category) ? Target.D_STANDARD : Target.D_HEAVY;
		long defence = (long) (t.getDefence() + 9) * (t.defensive(defType) + 64);
		double accuracy = hitChance(roll, defence);
		Npc npc = new Npc(t, Result.Kind.RANGED, key.equals("scorching bow"));
		double damage = accuracy * npc.mean(0, max, 1, 1, 0);
		if (key.equals("dark bow"))
		{
			// Two arrows each attack, each rolled on its own.
			damage *= 2;
		}

		Gear ammo = lo.get(Gear.AMMO);
		if ("Crossbow".equals(category) && ammo != null)
		{
			boolean zaryte = key.equals("zaryte crossbow");
			double diary = f.isKandarinHard() ? 1.1 : 1.0;
			if (ammo.key().startsWith("diamond bolts (e)") || ammo.key().startsWith("diamond dragon bolts (e)"))
			{
				// One bolt in ten pierces armour: it always hits, for up to 15% more.
				double chance = 0.1 * diary;
				double effect = npc.mean(0, max * (zaryte ? 126 : 115) / 100, 1, 1, 0);
				damage = chance * effect + (1 - chance) * damage;
			}
			else if (ammo.key().startsWith("ruby bolts (e)") || ammo.key().startsWith("ruby dragon bolts (e)"))
			{
				// Six in a hundred take a fifth of the monster's current health, up to 100, so the
				// effect is averaged over the whole kill rather than taken at full health.
				double chance = 0.06 * diary;
				double effect = rubyAverage(npc, t.getHp(), zaryte ? 22 : 20, zaryte ? 110 : 100);
				damage = chance * effect + (1 - chance) * damage;
			}
		}
		int ticks = Math.max(1, speed(weapon) - ("Rapid".equals(stance) ? 1 : 0));
		return new Result(Result.Kind.RANGED, damage / (ticks * TICK), max, accuracy, ticks, stance, prayer.name, null);
	}

	/** The ruby bolt's damage averaged over every health the monster passes through from full to dead. */
	static double rubyAverage(Npc npc, int hp, int percent, int cap)
	{
		if (hp <= 0)
		{
			return 0;
		}
		double sum = 0;
		for (int h = 1; h <= hp; h++)
		{
			sum += npc.hit(Math.max(1, Math.min(cap, h * percent / 100)));
		}
		return sum / hp;
	}

	/** Staves with their own spell built in, such as tridents and Tumeken's shadow. */
	private Result powered(Loadout lo, Totals tot, Fighter f, Target t, String stance)
	{
		Gear weapon = lo.weapon();
		if (weapon == null)
		{
			return Result.NONE;
		}
		int level = f.magic();
		String key = weapon.key();
		int base;
		if (key.startsWith("trident of the seas"))
		{
			base = Math.max(1, level / 3 - 5);
		}
		else if (key.startsWith("trident of the swamp"))
		{
			base = Math.max(1, level / 3 - 2);
		}
		else if (key.contains("sanguinesti staff"))
		{
			base = Math.max(1, level / 3);
		}
		else if (key.equals("tumeken's shadow"))
		{
			base = Math.max(1, level / 3 + 1);
		}
		else if (key.equals("eye of ayak"))
		{
			base = Math.max(1, level / 3 - 6);
		}
		else if (key.equals("warped sceptre"))
		{
			base = Math.max(1, (8 * level + 96) / 37);
		}
		else if (key.equals("accursed sceptre"))
		{
			base = Math.max(1, level / 3 - 6);
		}
		else if (key.equals("thammaron's sceptre"))
		{
			base = Math.max(1, level / 3 - 8);
		}
		else
		{
			return Result.NONE;
		}
		return magic(lo, tot, f, t, base, "Accurate".equals(stance) ? 2 : 0, speed(weapon), null, null, false,
			"Accurate".equals(stance) ? "Accurate" : "Longrange");
	}

	/** Staves that autocast a combat spell: the strongest fire spell, or ice from the Ancient Magicks. */
	private Result autocast(Loadout lo, Totals tot, Fighter f, Target t)
	{
		Result best = Result.NONE;
		int real = f.level("Magic");
		Gear weapon = lo.weapon();
		boolean harmonised = weapon != null && weapon.key().startsWith("harmonised nightmare staff");
		String[] fire = pick(STANDARD_SPELLS, real);
		if (fire != null)
		{
			best = magic(lo, tot, f, t, Integer.parseInt(fire[2]), 0, harmonised ? 4 : 5, fire[0], "fire", false, "Autocast");
		}
		String[] ice = f.isAncients() && autocastsAncients(weapon) ? pick(ANCIENT_SPELLS, real) : null;
		if (ice != null)
		{
			// Ice spells have no element, so no weakness applies to them.
			Result r = magic(lo, tot, f, t, Integer.parseInt(ice[2]), 0, 5, ice[0], null, true, "Autocast");
			if (r.isBetterThan(best))
			{
				best = r;
			}
		}
		return best;
	}

	/** Only some staves can autocast the Ancient Magicks. */
	static boolean autocastsAncients(Gear weapon)
	{
		if (weapon == null)
		{
			return false;
		}
		String key = weapon.key();
		for (String staff : ANCIENT_STAVES)
		{
			if (key.startsWith(staff))
			{
				return true;
			}
		}
		return key.contains("ancient sceptre");
	}

	private static String[] pick(String[][] spells, int level)
	{
		String[] best = null;
		for (String[] spell : spells)
		{
			if (level >= Integer.parseInt(spell[1]))
			{
				best = spell;
			}
		}
		return best;
	}

	private Result magic(Loadout lo, Totals tot, Fighter f, Target t, int base, int stanceBonus, int ticks,
		String spell, String element, boolean ancient, String style)
	{
		Gear weapon = lo.weapon();
		String key = weapon == null ? "" : weapon.key();
		Fighter.Prayer prayer = f.magicPrayer();
		int effMagic = f.magic() * prayer.accuracy / 100 + 9 + stanceBonus;
		if (voidSet(lo, "void mage helm", false))
		{
			effMagic = effMagic * 29 / 20;
		}
		int bonus = tot.offence[Gear.MAGIC];
		int damageBonus = tot.magicDamage;
		if (key.equals("tumeken's shadow"))
		{
			bonus *= 3;
			damageBonus = Math.min(1000, damageBonus * 3);
		}
		if (ancient)
		{
			// Each piece of virtus adds 3% to Ancient Magicks.
			damageBonus += 30 * ((lo.wears("virtus mask") ? 1 : 0) + (lo.wears("virtus robe top") ? 1 : 0)
				+ (lo.wears("virtus robe bottom") ? 1 : 0));
		}
		if (voidSet(lo, "void mage helm", true))
		{
			damageBonus += 50;
		}
		long baseRoll = (long) effMagic * (bonus + 64);
		long roll = baseRoll;
		boolean undead = t.is("undead");
		boolean mask = false;
		boolean revenant = revenantBonus(lo, t, "accursed sceptre", "thammaron's sceptre");
		if (undead && lo.wears("salve amulet(ei)"))
		{
			roll = roll * 120 / 100;
			damageBonus += 200;
		}
		else if (undead && lo.wears("salve amulet(i)"))
		{
			roll = roll * 115 / 100;
			damageBonus += 150;
		}
		else if (slayerBonus(lo, f, t, true))
		{
			mask = true;
		}
		if (mask)
		{
			roll = roll * 23 / 20;
		}
		if (revenant)
		{
			roll = roll * 3 / 2;
		}
		boolean weak = element != null && element.equals(t.weakness());
		if (weak)
		{
			roll += baseRoll * t.weaknessSeverity() / 100;
		}
		damageBonus += prayer.magicDamage;
		int max = base + base * damageBonus / 1000;
		if (mask)
		{
			max = max * 23 / 20;
		}
		if (revenant)
		{
			max = max * 3 / 2;
		}
		if (weak)
		{
			max += base * t.weaknessSeverity() / 100;
		}
		if ("fire".equals(element) && lo.wears("tome of fire"))
		{
			// A charged tome of fire adds a tenth to fire spells.
			max = max * 11 / 10;
		}
		long defence = (long) (t.getMagic() + 9) * (t.defensive(Target.D_MAGIC) + 64);
		double accuracy = hitChance(roll, defence);
		Npc npc = new Npc(t, Result.Kind.MAGIC, false);
		double perHit = npc.mean(0, max, 1, 1, 0);
		if (key.contains("sanguinesti staff"))
		{
			// One landed hit in five deals 8 more.
			perHit = 0.8 * perHit + 0.2 * npc.mean(0, max, 1, 1, 8);
		}
		double damage = accuracy * perHit;
		return new Result(Result.Kind.MAGIC, damage / (ticks * TICK), max, accuracy, ticks, style, prayer.name, spell);
	}

	/** Whether a revenant weapon, kept charged, gets its half again against a Wilderness monster. */
	private static boolean revenantBonus(Loadout lo, Target t, String... weapons)
	{
		Gear weapon = lo.weapon();
		if (weapon == null || !t.isWilderness())
		{
			return false;
		}
		for (String w : weapons)
		{
			if (weapon.key().equals(w))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * What one landed hit is worth against a target: the game raises an accurate 0 to 1, then the
	 * target's own rules apply, such as Zulrah's cap on big hits, the Kraken shrugging off ranged
	 * attacks, the Tormented demon's shield and flat armour.
	 */
	static final class Npc
	{
		private final boolean zulrah;
		private final int halve;
		private final int divisor;
		private final boolean shielded;
		private final int flat;

		Npc(Target t, Result.Kind kind, boolean bane)
		{
			this(t, kind, bane, kind == Result.Kind.MAGIC);
		}

		/** Corpbane weapons (stabbing spears and halberds, the fang, and magic) hurt the Corporeal Beast in full. */
		Npc(Target t, Result.Kind kind, boolean bane, boolean corpbane)
		{
			String name = t.getName();
			zulrah = "Zulrah".equals(name);
			halve = "Corporeal Beast".equals(name) && !corpbane ? 2 : 1;
			divisor = kind == Result.Kind.RANGED && "Kraken".equals(name) ? 7 : 1;
			shielded = "Tormented Demon".equals(name) && !bane;
			flat = kind == Result.Kind.MAGIC ? 0 : t.getFlatArmour();
		}

		/** The mean of a landed hit rolled from lo to hi, each scaled by num/den and given add. */
		double mean(int lo, int hi, int num, int den, int add)
		{
			if (hi <= 0 && add <= 0)
			{
				return 0;
			}
			int top = Math.max(lo, hi);
			double sum = 0;
			for (int h = lo; h <= top; h++)
			{
				// The Corporeal Beast halves hits after the 0 is raised to 1.
				sum += hit(Math.max(1, h * num / den + add) / halve);
			}
			return sum / (top - lo + 1);
		}

		/** One landed hitsplat after the target's rules. */
		double hit(int h)
		{
			if (zulrah && h > 50)
			{
				// Zulrah turns any hit over 50 into one from 45 to 50.
				double sum = 0;
				for (int i = 45; i <= 50; i++)
				{
					sum += rest(i);
				}
				return sum / 6;
			}
			return rest(h);
		}

		private double rest(int h)
		{
			int d = h >= 1 ? Math.max(1, h / divisor) : 0;
			if (shielded)
			{
				// A shielded Tormented demon takes a fifth less from anything but demonbane and abyssal weapons.
				d = Math.max(d >= 1 ? 1 : d, d * 4 / 5);
			}
			return Math.max(0, d - flat);
		}
	}

	private static boolean slayerBonus(Loadout lo, Fighter f, Target t, boolean imbuedOnly)
	{
		if (!f.onTaskFor(t))
		{
			return false;
		}
		Gear head = lo.get(Gear.HEAD);
		if (head == null)
		{
			return false;
		}
		String key = head.key();
		boolean mask = key.contains("slayer helmet") || key.startsWith("black mask");
		return mask && (!imbuedOnly || key.contains("(i)"));
	}

	private static boolean tzhaarWeapon(Loadout lo)
	{
		Gear weapon = lo.weapon();
		if (weapon == null)
		{
			return false;
		}
		String key = weapon.key();
		return key.startsWith("toktz-xil-") || key.startsWith("tzhaar-ket-") || key.startsWith("toktz-mej-");
	}

	/** Whether a full void set with the given helm is worn; elite asks for the elite top and robe. */
	private static boolean voidSet(Loadout lo, String helm, boolean elite)
	{
		if (!lo.wears(helm) || !lo.wears("void knight gloves"))
		{
			return false;
		}
		boolean eliteSet = lo.wears("elite void top") && lo.wears("elite void robe");
		if (elite)
		{
			return eliteSet;
		}
		return eliteSet || lo.wears("void knight top") && lo.wears("void knight robe");
	}

	private static int speed(Gear weapon)
	{
		return weapon == null || weapon.getSpeed() <= 0 ? 4 : weapon.getSpeed();
	}

	static double hitChance(long attack, long defence)
	{
		if (attack > defence)
		{
			return 1 - (defence + 2.0) / (2.0 * (attack + 1));
		}
		return attack / (2.0 * (defence + 1));
	}

	/** Osmumten's fang rolls its accuracy twice and keeps the better one. */
	static double fangChance(long attack, long defence)
	{
		double a = attack;
		double d = defence;
		if (attack > defence)
		{
			return 1 - (d + 2) * (2 * d + 3) / (6 * (a + 1) * (a + 1));
		}
		return a * (4 * a + 5) / (6 * (a + 1) * (d + 1));
	}

	/** The twisted bow's scaling with the target's magic, for accuracy or damage. */
	static long twistedBow(long value, int magic, boolean accuracy)
	{
		int factor = accuracy ? 10 : 14;
		int base = accuracy ? 140 : 250;
		long t2 = (3L * magic - factor) / 100;
		long inner = 3L * magic / 10 - 10L * factor;
		long t3 = inner * inner / 100;
		long bonus = Math.max(0, Math.min(base, base + t2 - t3));
		return value * bonus / 100;
	}

	private static String capital(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Target;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * The player as the formulas need them: real levels, which potions and prayers to
 * assume, which offensive prayers they have unlocked and the spellbook they can use.
 */
public final class Fighter
{
	public enum Boost
	{
		NONE("No potions"),
		POTIONS("Combat potions"),
		BEST("Best boosts");

		private final String label;

		Boost(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	private final Map<String, Integer> levels;
	private final Boost boost;
	private final boolean prayers;
	private final boolean piety;
	private final boolean rigour;
	private final boolean augury;
	private final boolean ancients;
	private final SlayerTask task;
	private boolean deadeye;
	private boolean vigour;
	private boolean kandarinHard;

	public Fighter(Map<String, Integer> levels, Boost boost, boolean prayers, boolean piety, boolean rigour, boolean augury,
		boolean ancients, boolean onTask)
	{
		this(levels, boost, prayers, piety, rigour, augury, ancients, onTask ? SlayerTask.ALWAYS : SlayerTask.NEVER);
	}

	public Fighter(Map<String, Integer> levels, Boost boost, boolean prayers, boolean piety, boolean rigour, boolean augury,
		boolean ancients, SlayerTask task)
	{
		this.levels = levels == null ? Collections.emptyMap() : new HashMap<>(levels);
		this.boost = boost == null ? Boost.NONE : boost;
		this.prayers = prayers;
		this.piety = piety;
		this.rigour = rigour;
		this.augury = augury;
		this.ancients = ancients;
		this.task = task == null ? SlayerTask.NEVER : task;
	}

	/**
	 * The same fighter with the prayer scrolls read from the game (Deadeye and Mystic Vigour)
	 * and whether the Kandarin hard diary is done, which makes enchanted bolts trigger more often.
	 */
	public Fighter withUnlocks(boolean deadeye, boolean vigour, boolean kandarinHard)
	{
		Fighter f = new Fighter(levels, boost, prayers, piety, rigour, augury, ancients, task);
		f.deadeye = deadeye;
		f.vigour = vigour;
		f.kandarinHard = kandarinHard;
		return f;
	}

	/** A maxed account with every unlock, used for previews and tests. */
	public static Fighter maxed(Boost boost)
	{
		Map<String, Integer> levels = new HashMap<>();
		for (String skill : new String[]{"Attack", "Strength", "Defence", "Ranged", "Magic", "Prayer", "Hitpoints", "Agility"})
		{
			levels.put(skill, 99);
		}
		return new Fighter(levels, boost, true, true, true, true, true, false).withUnlocks(true, true, true);
	}

	public int level(String skill)
	{
		Integer level = levels.get(skill);
		return level == null ? 1 : level;
	}

	public Map<String, Integer> getLevels()
	{
		return Collections.unmodifiableMap(levels);
	}

	public Boost getBoost()
	{
		return boost;
	}

	public boolean isAncients()
	{
		return ancients;
	}

	public SlayerTask getTask()
	{
		return task;
	}

	/** Whether the black mask and slayer helmet count against this target. */
	public boolean onTaskFor(Target target)
	{
		return task.covers(target);
	}

	public boolean isKandarinHard()
	{
		return kandarinHard;
	}

	/** Everything that changes the numbers besides levels and gear, for caching. */
	public String assumptions()
	{
		return boost + "/" + prayers + piety + rigour + augury + deadeye + vigour + "/" + ancients + kandarinHard + "/" + task;
	}

	/** Whether the player meets every level an item asks for. */
	public boolean meets(Map<String, Integer> requirements)
	{
		for (Map.Entry<String, Integer> r : requirements.entrySet())
		{
			if (level(r.getKey()) < r.getValue())
			{
				return false;
			}
		}
		return true;
	}

	/** The first requirement not met, as "75 Ranged", or null. */
	public String missing(Map<String, Integer> requirements)
	{
		for (Map.Entry<String, Integer> r : requirements.entrySet())
		{
			if (level(r.getKey()) < r.getValue())
			{
				return r.getValue() + " " + r.getKey();
			}
		}
		return null;
	}

	/** How many levels in all the fighter is short of these requirements. */
	public int shortfall(Map<String, Integer> requirements)
	{
		int total = 0;
		for (Map.Entry<String, Integer> r : requirements.entrySet())
		{
			total += Math.max(0, r.getValue() - level(r.getKey()));
		}
		return total;
	}

	int attack()
	{
		return melee(level("Attack"));
	}

	int strength()
	{
		return melee(level("Strength"));
	}

	private int melee(int level)
	{
		// Super combat potion: 5 plus 15%.
		return boost == Boost.NONE ? level : level + 5 + level * 15 / 100;
	}

	int ranged()
	{
		int level = level("Ranged");
		// Ranging potion: 4 plus 10%.
		return boost == Boost.NONE ? level : level + 4 + level / 10;
	}

	int magic()
	{
		int level = level("Magic");
		switch (boost)
		{
			case POTIONS:
				// Magic potion.
				return level + 4;
			case BEST:
				// Saturated heart.
				return level + 4 + level / 10;
			default:
				return level;
		}
	}

	/** The best melee prayer as accuracy and strength percentages, with its name. */
	Prayer meleePrayer()
	{
		int prayer = level("Prayer");
		int defence = level("Defence");
		if (!prayers)
		{
			return Prayer.NONE;
		}
		if (piety && prayer >= 70 && defence >= 70)
		{
			return new Prayer("Piety", 120, 123, 0);
		}
		if (piety && prayer >= 60 && defence >= 65)
		{
			return new Prayer("Chivalry", 115, 118, 0);
		}
		int accuracy = prayer >= 34 ? 115 : prayer >= 16 ? 110 : prayer >= 7 ? 105 : 100;
		int damage = prayer >= 31 ? 115 : prayer >= 13 ? 110 : prayer >= 4 ? 105 : 100;
		if (prayer >= 34)
		{
			return new Prayer("Incredible Reflexes and Ultimate Strength", accuracy, damage, 0);
		}
		return accuracy == 100 && damage == 100 ? Prayer.NONE : new Prayer("Offensive prayers", accuracy, damage, 0);
	}

	Prayer rangedPrayer()
	{
		int prayer = level("Prayer");
		if (!prayers)
		{
			return Prayer.NONE;
		}
		if (rigour && prayer >= 74 && level("Defence") >= 70)
		{
			return new Prayer("Rigour", 120, 123, 0);
		}
		if (deadeye && prayer >= 62)
		{
			return new Prayer("Deadeye", 118, 118, 0);
		}
		if (prayer >= 44)
		{
			return new Prayer("Eagle Eye", 115, 115, 0);
		}
		if (prayer >= 26)
		{
			return new Prayer("Hawk Eye", 110, 110, 0);
		}
		return prayer >= 8 ? new Prayer("Sharp Eye", 105, 105, 0) : Prayer.NONE;
	}

	Prayer magicPrayer()
	{
		int prayer = level("Prayer");
		if (!prayers)
		{
			return Prayer.NONE;
		}
		if (augury && prayer >= 77 && level("Defence") >= 70)
		{
			return new Prayer("Augury", 125, 100, 40);
		}
		if (vigour && prayer >= 63)
		{
			return new Prayer("Mystic Vigour", 118, 100, 30);
		}
		if (prayer >= 45)
		{
			return new Prayer("Mystic Might", 115, 100, 20);
		}
		if (prayer >= 27)
		{
			return new Prayer("Mystic Lore", 110, 100, 10);
		}
		return prayer >= 9 ? new Prayer("Mystic Will", 105, 100, 0) : Prayer.NONE;
	}

	/** An offensive prayer: accuracy and strength as percentages, and magic damage in tenths of a percent. */
	static final class Prayer
	{
		static final Prayer NONE = new Prayer(null, 100, 100, 0);

		final String name;
		final int accuracy;
		final int strength;
		final int magicDamage;

		Prayer(String name, int accuracy, int strength, int magicDamage)
		{
			this.name = name;
			this.accuracy = accuracy;
			this.strength = strength;
			this.magicDamage = magicDamage;
		}
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Gear;
import java.util.Arrays;

/** Eleven equipment slots. Changes return a new loadout, so loadouts can be shared freely. */
public final class Loadout
{
	private static final Loadout EMPTY = new Loadout(new Gear[Gear.SLOTS]);

	private final Gear[] slots;

	private Loadout(Gear[] slots)
	{
		this.slots = slots;
	}

	public static Loadout empty()
	{
		return EMPTY;
	}

	public static Loadout of(Gear... gear)
	{
		Loadout loadout = EMPTY;
		for (Gear g : gear)
		{
			if (g != null)
			{
				loadout = loadout.with(g);
			}
		}
		return loadout;
	}

	public Gear get(int slot)
	{
		return slots[slot];
	}

	public Gear weapon()
	{
		return slots[Gear.WEAPON];
	}

	/** Wears a piece in its own slot; a two-handed weapon takes the shield off, and a shield takes a two-hander off. */
	public Loadout with(Gear gear)
	{
		Gear[] next = slots.clone();
		next[gear.getSlot()] = gear;
		if (gear.getSlot() == Gear.WEAPON && gear.isTwoHanded())
		{
			next[Gear.SHIELD] = null;
		}
		if (gear.getSlot() == Gear.SHIELD && next[Gear.WEAPON] != null && next[Gear.WEAPON].isTwoHanded())
		{
			next[Gear.WEAPON] = null;
		}
		return new Loadout(next);
	}

	public Loadout without(int slot)
	{
		Gear[] next = slots.clone();
		next[slot] = null;
		return new Loadout(next);
	}

	public boolean wears(String key)
	{
		for (Gear g : slots)
		{
			if (g != null && g.key().equals(key))
			{
				return true;
			}
		}
		return false;
	}

	public boolean wearsAny(String... keys)
	{
		for (String key : keys)
		{
			if (wears(key))
			{
				return true;
			}
		}
		return false;
	}

	public boolean contains(Gear gear)
	{
		return gear != null && slots[gear.getSlot()] == gear;
	}

	@Override
	public boolean equals(Object o)
	{
		return o instanceof Loadout && Arrays.equals(slots, ((Loadout) o).slots);
	}

	@Override
	public int hashCode()
	{
		return Arrays.hashCode(slots);
	}

	@Override
	public String toString()
	{
		return Arrays.toString(slots);
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.CatalogueEntry;
import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.RoadmapData;
import com.codex.gearroadmap.data.Target;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Finds the best loadout a player can put together from what they own, for each kind of
 * attack, by trying their strongest weapons and then improving one slot at a time until
 * no single swap helps. The same search answers "what if I also owned this?" for every
 * upgrade the roadmap weighs.
 */
public final class Planner
{
	/** Slots in the order they are improved; the weapon is chosen first and held. */
	private static final int[] ORDER = {Gear.AMMO, Gear.BODY, Gear.LEGS, Gear.HEAD, Gear.SHIELD, Gear.NECK, Gear.CAPE,
		Gear.HANDS, Gear.FEET, Gear.RING};
	private static final int WEAPONS_TRIED = 5;
	private static final String[][] SETS = {
		{"void melee helm", "void knight top", "void knight robe", "void knight gloves"},
		{"void ranger helm", "void knight top", "void knight robe", "void knight gloves"},
		{"void mage helm", "void knight top", "void knight robe", "void knight gloves"},
		{"void ranger helm", "elite void top", "elite void robe", "void knight gloves"},
		{"void mage helm", "elite void top", "elite void robe", "void knight gloves"},
		{"obsidian helmet", "obsidian platebody", "obsidian platelegs"},
	};

	/** One loadout and what it does. */
	public static final class Plan
	{
		private final Loadout loadout;
		private final Result result;

		Plan(Loadout loadout, Result result)
		{
			this.loadout = loadout;
			this.result = result;
		}

		public Loadout getLoadout()
		{
			return loadout;
		}

		public Result getResult()
		{
			return result;
		}

		public double dps()
		{
			return result.getDps();
		}
	}

	/** The best plan for each kind of attack, and the best of them. */
	public static final class Best
	{
		private final Map<Result.Kind, Plan> plans;
		private final Plan best;

		Best(Map<Result.Kind, Plan> plans)
		{
			this.plans = plans;
			Plan top = null;
			for (Plan p : plans.values())
			{
				if (top == null || p.dps() > top.dps() + 1e-9)
				{
					top = p;
				}
			}
			this.best = top == null ? new Plan(Loadout.empty(), Result.NONE) : top;
		}

		public Plan get(Result.Kind kind)
		{
			return plans.get(kind);
		}

		public Plan best()
		{
			return best;
		}

		public double dps()
		{
			return best.dps();
		}
	}

	private final RoadmapData data;
	private final Calc calc;

	public Planner(RoadmapData data)
	{
		this.data = data;
		this.calc = new Calc(data);
	}

	public Calc calc()
	{
		return calc;
	}

	/** The best loadouts from the gear owned. */
	public Best optimise(Collection<Gear> owned, Fighter fighter, Target target)
	{
		Map<Result.Kind, Plan> plans = new EnumMap<>(Result.Kind.class);
		for (Result.Kind kind : Result.Kind.values())
		{
			plans.put(kind, target.allows(kind.name()) ? optimise(owned, fighter, target, kind) : new Plan(Loadout.empty(), Result.NONE));
		}
		return new Best(plans);
	}

	private Plan optimise(Collection<Gear> owned, Fighter fighter, Target target, Result.Kind kind)
	{
		List<List<Gear>> bySlot = bySlot(owned, fighter, kind);
		List<Plan> weapons = new ArrayList<>();
		for (Gear weapon : bySlot.get(Gear.WEAPON))
		{
			Loadout start = withAmmo(Loadout.of(weapon), bySlot, fighter, target, kind);
			weapons.add(new Plan(start, calc.best(start, fighter, target, kind)));
		}
		if (kind == Result.Kind.MELEE)
		{
			weapons.add(new Plan(Loadout.empty(), calc.best(Loadout.empty(), fighter, target, kind)));
		}
		weapons.sort(Comparator.comparingDouble((Plan p) -> -p.dps()));

		Plan best = new Plan(Loadout.empty(), Result.NONE);
		int tried = 0;
		for (Plan start : weapons)
		{
			if (start.dps() <= 0 && kind != Result.Kind.MELEE || tried++ >= WEAPONS_TRIED)
			{
				break;
			}
			Plan p = ascend(start.getLoadout(), bySlot, fighter, target, kind, -1, 3);
			if (p.dps() > best.dps() + 1e-9)
			{
				best = p;
			}
			for (String[] set : SETS)
			{
				Loadout seeded = seed(start.getLoadout(), set, bySlot);
				if (seeded != null)
				{
					Plan s = ascend(seeded, bySlot, fighter, target, kind, -1, 3);
					if (s.dps() > best.dps() + 1e-9)
					{
						best = s;
					}
				}
			}
		}
		return best;
	}

	/**
	 * The best overall plan if the player also owned these pieces, starting from the plans
	 * they already have. Faster than a fresh search, and the same answer in practice.
	 */
	public Plan withAdded(Best current, Collection<Gear> owned, List<Gear> added, Fighter fighter, Target target)
	{
		Set<Gear> all = new LinkedHashSet<>(owned);
		all.addAll(added);
		Plan best = current.best();
		for (Result.Kind kind : Result.Kind.values())
		{
			if (!fits(added, kind) || !target.allows(kind.name()))
			{
				continue;
			}
			List<List<Gear>> bySlot = bySlot(all, fighter, kind);
			Plan from = current.get(kind);
			Loadout start = from == null || from.dps() <= 0 ? Loadout.empty() : from.getLoadout();
			int locked = -1;
			for (Gear g : added)
			{
				if (g.getSlot() == Gear.SHIELD && start.weapon() != null && start.weapon().isTwoHanded())
				{
					start = oneHanded(start, g, bySlot, fighter, target, kind);
				}
				start = start.with(g);
				locked = added.size() == 1 ? g.getSlot() : -1;
			}
			if (start.weapon() == null && kind != Result.Kind.MELEE)
			{
				continue;
			}
			if (start.weapon() != null && containsWeapon(added))
			{
				start = withAmmo(start, bySlot, fighter, target, kind);
			}
			Plan p = ascend(start, bySlot, fighter, target, kind, locked, 2);
			if (p.dps() > best.dps() + 1e-9)
			{
				best = p;
			}
		}
		return best;
	}

	/** Swaps a two-handed weapon for the best one-handed one, so a shield can be tried. */
	private Loadout oneHanded(Loadout lo, Gear shield, List<List<Gear>> bySlot, Fighter fighter, Target target, Result.Kind kind)
	{
		Loadout best = lo.without(Gear.WEAPON);
		Result bestResult = calc.best(best.with(shield), fighter, target, kind);
		for (Gear weapon : bySlot.get(Gear.WEAPON))
		{
			if (weapon.isTwoHanded())
			{
				continue;
			}
			Loadout next = withAmmo(lo.with(weapon), bySlot, fighter, target, kind);
			Result r = calc.best(next.with(shield), fighter, target, kind);
			if (r.isBetterThan(bestResult))
			{
				best = next;
				bestResult = r;
			}
		}
		return best;
	}

	private static boolean containsWeapon(List<Gear> gear)
	{
		for (Gear g : gear)
		{
			if (g.getSlot() == Gear.WEAPON)
			{
				return true;
			}
		}
		return false;
	}

	/** Whether any of the pieces can matter to this kind of attack. */
	private boolean fits(List<Gear> added, Result.Kind kind)
	{
		for (Gear g : added)
		{
			if (relevant(g, kind))
			{
				return true;
			}
		}
		return false;
	}

	private Plan ascend(Loadout loadout, List<List<Gear>> bySlot, Fighter fighter, Target target, Result.Kind kind,
		int lockedSlot, int passes)
	{
		Loadout lo = loadout;
		Result current = calc.best(lo, fighter, target, kind);
		for (int pass = 0; pass < passes; pass++)
		{
			boolean changed = false;
			for (int slot : ORDER)
			{
				if (slot == lockedSlot || slot == Gear.SHIELD && lo.weapon() != null && lo.weapon().isTwoHanded())
				{
					continue;
				}
				Loadout bestLo = lo;
				Result bestResult = current;
				if (lo.get(slot) != null)
				{
					Loadout bare = lo.without(slot);
					Result r = calc.best(bare, fighter, target, kind);
					if (r.isBetterThan(bestResult))
					{
						bestLo = bare;
						bestResult = r;
					}
				}
				for (Gear g : bySlot.get(slot))
				{
					if (lo.get(slot) == g)
					{
						continue;
					}
					Loadout next = lo.with(g);
					Result r = calc.best(next, fighter, target, kind);
					if (r.isBetterThan(bestResult))
					{
						bestLo = next;
						bestResult = r;
					}
				}
				if (bestLo != lo)
				{
					lo = bestLo;
					current = bestResult;
					changed = true;
				}
			}
			if (!changed)
			{
				break;
			}
		}
		return new Plan(lo, current);
	}

	/** Loads the best ammunition the player owns for a weapon that needs it. */
	private Loadout withAmmo(Loadout lo, List<List<Gear>> bySlot, Fighter fighter, Target target, Result.Kind kind)
	{
		Set<Integer> fires = data.ammoFor(lo.weapon());
		if (fires == null || fires.isEmpty())
		{
			return lo;
		}
		Loadout best = lo;
		Result bestResult = calc.best(lo, fighter, target, kind);
		for (Gear ammo : bySlot.get(Gear.AMMO))
		{
			Loadout next = lo.with(ammo);
			Result r = calc.best(next, fighter, target, kind);
			if (r.isBetterThan(bestResult))
			{
				best = next;
				bestResult = r;
			}
		}
		return best;
	}

	private Loadout seed(Loadout start, String[] set, List<List<Gear>> bySlot)
	{
		Loadout lo = start;
		for (String key : set)
		{
			Gear piece = null;
			for (List<Gear> slot : bySlot)
			{
				for (Gear g : slot)
				{
					if (g.key().equals(key))
					{
						piece = g;
					}
				}
			}
			if (piece == null)
			{
				return null;
			}
			lo = lo.with(piece);
		}
		return lo;
	}

	/** The owned pieces worth trying in each slot for one kind of attack, keeping only what the player can wield. */
	private List<List<Gear>> bySlot(Collection<Gear> owned, Fighter fighter, Result.Kind kind)
	{
		List<List<Gear>> slots = new ArrayList<>();
		for (int i = 0; i < Gear.SLOTS; i++)
		{
			slots.add(new ArrayList<>());
		}
		Set<Gear> seen = new HashSet<>();
		for (Gear g : owned)
		{
			if (g == null || !seen.add(g) || !wieldable(g, fighter))
			{
				continue;
			}
			if (g.getSlot() == Gear.WEAPON ? usesKind(g, kind) : relevant(g, kind))
			{
				slots.get(g.getSlot()).add(g);
			}
		}
		return slots;
	}

	public boolean wieldable(Gear gear, Fighter fighter)
	{
		CatalogueEntry entry = data.entry(gear);
		return entry == null || fighter.meets(entry.getRequirements());
	}

	/** Whether a weapon offers an attack of this kind. */
	public boolean usesKind(Gear weapon, Result.Kind kind)
	{
		for (RoadmapData.Style style : data.styles(weapon.getCategory()))
		{
			String type = style.getType();
			Result.Kind k = "magic".equals(type) ? Result.Kind.MAGIC : "ranged".equals(type) ? Result.Kind.RANGED : Result.Kind.MELEE;
			if (k == kind)
			{
				return true;
			}
		}
		return false;
	}

	/** Whether a piece can raise damage for this kind of attack. */
	boolean relevant(Gear g, Result.Kind kind)
	{
		if (g.getSlot() == Gear.WEAPON)
		{
			return usesKind(g, kind);
		}
		String key = g.key();
		if (key.startsWith("salve amulet") || key.contains("slayer helmet") || key.startsWith("black mask")
			|| key.startsWith("void ") || key.startsWith("elite void") || key.startsWith("obsidian") || key.startsWith("crystal "))
		{
			return true;
		}
		switch (kind)
		{
			case MELEE:
				return g.offence(Gear.STAB) > 0 || g.offence(Gear.SLASH) > 0 || g.offence(Gear.CRUSH) > 0 || g.strength() > 0;
			case RANGED:
				return g.offence(Gear.RANGED) > 0 || g.rangedStrength() > 0;
			default:
				return g.offence(Gear.MAGIC) > 0 || g.magicDamage() > 0;
		}
	}
}

package com.codex.gearroadmap.core;

import java.util.Collections;
import java.util.List;

/** One snapshot for the panel: the roadmap for the focused target and the survey of every target. */
public final class Report
{
	private final boolean loggedIn;
	private final Roadmap roadmap;
	private final List<Roadmap.Survey> survey;
	private final String boosts;
	private final int owned;
	private final boolean bankSeen;
	private boolean ironman;
	private boolean seasonal;
	private String task;
	private Boolean slayer;

	public Report(boolean loggedIn, Roadmap roadmap, List<Roadmap.Survey> survey, String boosts, int owned, boolean bankSeen)
	{
		this.loggedIn = loggedIn;
		this.roadmap = roadmap;
		this.survey = survey == null ? Collections.emptyList() : survey;
		this.boosts = boosts;
		this.owned = owned;
		this.bankSeen = bankSeen;
	}

	/** A copy that knows the account: ironmen cannot buy, and seasonal worlds have their own economy. */
	public Report withAccount(boolean ironman, boolean seasonal, String task)
	{
		return withAccount(ironman, seasonal, task, null);
	}

	/** As above, with whether the slayer helmet counts against the aimed target, or null when it is no slayer monster. */
	public Report withAccount(boolean ironman, boolean seasonal, String task, Boolean slayer)
	{
		Report r = new Report(loggedIn, roadmap, survey, boosts, owned, bankSeen);
		r.ironman = ironman;
		r.seasonal = seasonal;
		r.task = task;
		r.slayer = slayer;
		return r;
	}

	/** A copy with another roadmap, such as the same road with the player's coins updated. */
	public Report withRoadmap(Roadmap roadmap)
	{
		return new Report(loggedIn, roadmap, survey, boosts, owned, bankSeen).withAccount(ironman, seasonal, task, slayer);
	}

	public static Report loggedOut()
	{
		return new Report(false, null, null, null, 0, false);
	}

	public boolean isLoggedIn()
	{
		return loggedIn;
	}

	/** Null until the first plan is ready. */
	public Roadmap getRoadmap()
	{
		return roadmap;
	}

	public List<Roadmap.Survey> getSurvey()
	{
		return survey;
	}

	/** The potions assumed, as the config names them. */
	public String getBoosts()
	{
		return boosts;
	}

	/** How many pieces of combat gear the player owns. */
	public int getOwned()
	{
		return owned;
	}

	/** Ironmen cannot buy from the Grand Exchange, so prices stand for how hard an item is to get. */
	public boolean isIronman()
	{
		return ironman;
	}

	public boolean isSeasonal()
	{
		return seasonal;
	}

	/** Whether the slayer helmet counts against the aimed target; null when it is not a slayer monster. */
	public Boolean getSlayer()
	{
		return slayer;
	}

	/** The current slayer task's name, lower case, or null. */
	public String getTask()
	{
		return task;
	}

	/** Whether the bank has been read, so the owned list is complete. */
	public boolean isBankSeen()
	{
		return bankSeen;
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Target;

/** What one loadout does to one target with its best attack style. */
public final class Result
{
	public enum Kind
	{
		MELEE("Melee"),
		RANGED("Ranged"),
		MAGIC("Magic");

		private final String label;

		Kind(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	static final Result NONE = new Result(null, 0, 0, 0, 0, null, null, null);

	private final Kind kind;
	private final double dps;
	private final int maxHit;
	private final double accuracy;
	private final int ticks;
	private final String style;
	private final String prayer;
	private final String spell;

	Result(Kind kind, double dps, int maxHit, double accuracy, int ticks, String style, String prayer, String spell)
	{
		this.kind = kind;
		this.dps = dps;
		this.maxHit = maxHit;
		this.accuracy = accuracy;
		this.ticks = ticks;
		this.style = style;
		this.prayer = prayer;
		this.spell = spell;
	}

	public Kind getKind()
	{
		return kind;
	}

	/** Expected damage per second. */
	public double getDps()
	{
		return dps;
	}

	public int getMaxHit()
	{
		return maxHit;
	}

	/** Chance each attack hits. */
	public double getAccuracy()
	{
		return accuracy;
	}

	/** Game ticks between attacks. */
	public int getTicks()
	{
		return ticks;
	}

	/** The attack style chosen, such as "Slash, aggressive" or "Rapid". */
	public String getStyle()
	{
		return style;
	}

	public String getPrayer()
	{
		return prayer;
	}

	public String getSpell()
	{
		return spell;
	}

	/** Seconds to kill the target at this rate, ignoring overkill and downtime. */
	public double secondsToKill(Target target)
	{
		return dps <= 0 ? Double.POSITIVE_INFINITY : target.getHp() / dps;
	}

	public boolean isBetterThan(Result other)
	{
		return other == null || dps > other.dps + 1e-9;
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Gear;
import com.codex.gearroadmap.data.Target;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Everything the panel shows for one target: the loadouts owned now and the upgrades ahead. */
public final class Roadmap
{
	/** One upgrade weighed against the loadout it would join. */
	public static final class Option
	{
		private final String name;
		private final List<Gear> pieces;
		private final Gear icon;
		private final long cost;
		private final double gain;
		private final double before;
		private final Planner.Plan after;
		private final String missing;
		private final String earn;
		private final String note;
		private final boolean ammo;

		Option(String name, List<Gear> pieces, Gear icon, long cost, double gain, double before, Planner.Plan after,
			String missing, String earn, String note, boolean ammo)
		{
			this.name = name;
			this.pieces = pieces;
			this.icon = icon;
			this.cost = cost;
			this.gain = gain;
			this.before = before;
			this.after = after;
			this.missing = missing;
			this.earn = earn;
			this.note = note;
			this.ammo = ammo;
		}

		public String getName()
		{
			return name;
		}

		public List<Gear> getPieces()
		{
			return pieces;
		}

		public Gear getIcon()
		{
			return icon;
		}

		/** Coins to buy it; 0 when it is earned or made from gear already owned. */
		public long getCost()
		{
			return cost;
		}

		/** Damage per second it adds. */
		public double getGain()
		{
			return gain;
		}

		/** The gain as a share of the damage before it. */
		public double getGainShare()
		{
			return before <= 0 ? 0 : gain / before;
		}

		public Planner.Plan getAfter()
		{
			return after;
		}

		/** The level still missing to wield it, such as "80 Ranged", or null. */
		public String getMissing()
		{
			return missing;
		}

		public String getEarn()
		{
			return earn;
		}

		public String getNote()
		{
			return note;
		}

		/** Ammunition is priced per thousand. */
		public boolean isAmmo()
		{
			return ammo;
		}
	}

	/** One step of the road, with what the road has cost up to and including it. */
	public static final class Step
	{
		private final Option option;
		private final long spent;
		private final boolean affordable;

		Step(Option option, long spent, boolean affordable)
		{
			this.option = option;
			this.spent = spent;
			this.affordable = affordable;
		}

		public Option getOption()
		{
			return option;
		}

		public long getSpent()
		{
			return spent;
		}

		/** Whether the player's coins already cover the road up to here. */
		public boolean isAffordable()
		{
			return affordable;
		}
	}

	/** One target in the Targets list: the best the player can do there now. */
	public static final class Survey
	{
		private final Target target;
		private final Planner.Plan plan;

		Survey(Target target, Planner.Plan plan)
		{
			this.target = target;
			this.plan = plan;
		}

		public Target getTarget()
		{
			return target;
		}

		public Planner.Plan getPlan()
		{
			return plan;
		}
	}

	private final Target target;
	private final Planner.Best now;
	private final List<Step> path;
	private final List<Option> free;
	private final List<Option> locked;
	private final List<Option> leaps;
	private final long coins;

	Roadmap(Target target, Planner.Best now, List<Step> path, List<Option> free, List<Option> locked, List<Option> leaps, long coins)
	{
		this.target = target;
		this.now = now;
		this.path = path;
		this.free = free;
		this.locked = locked;
		this.leaps = leaps;
		this.coins = coins;
	}

	public Target getTarget()
	{
		return target;
	}

	/** The same road, with what the player's coins now cover. */
	public Roadmap withCoins(long coins)
	{
		List<Step> steps = new ArrayList<>();
		for (Step s : path)
		{
			steps.add(new Step(s.option, s.spent, s.spent <= coins));
		}
		List<Option> bought = new ArrayList<>(leaps);
		return new Roadmap(target, now, steps, free, locked, bought, coins);
	}

	public Planner.Best getNow()
	{
		return now;
	}

	public List<Step> getPath()
	{
		return Collections.unmodifiableList(path);
	}

	public List<Option> getFree()
	{
		return free;
	}

	public List<Option> getLocked()
	{
		return locked;
	}

	public List<Option> getLeaps()
	{
		return leaps;
	}

	public long getCoins()
	{
		return coins;
	}

	/** Damage per second at the end of the road. */
	public double finalDps()
	{
		return path.isEmpty() ? now.dps() : path.get(path.size() - 1).getOption().getAfter().dps();
	}
}

package com.codex.gearroadmap.core;

import com.codex.gearroadmap.data.Target;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Whether the black mask and slayer helmet count against a target. Slayer creatures are
 * nearly always killed on task, bosses and training spots seldom are, so by default the
 * bonus counts for Slayer creatures and for anything the player's current task covers.
 */
public final class SlayerTask
{
	public enum Mode
	{
		SMART("Slayer monsters and your task"),
		ALWAYS("Always"),
		NEVER("Never");

		private final String label;

		Mode(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	public static final SlayerTask ALWAYS = new SlayerTask(Mode.ALWAYS, null);
	public static final SlayerTask NEVER = new SlayerTask(Mode.NEVER, null);

	/** Tasks that also cover a boss or monster besides its own name, as the Slayer helper lists them. */
	private static final Map<String, Set<String>> COVERED_BY = new HashMap<>();

	static
	{
		cover("vorkath", "blue dragons", "zombies");
		cover("kree'arra", "aviansies");
		cover("k'ril tsutsaroth", "greater demons");
		cover("cerberus", "hellhounds");
		cover("abyssal sire", "abyssal demons");
		cover("alchemical hydra", "hydras");
		cover("kraken", "cave kraken", "cave kraken boss");
		cover("thermonuclear smoke devil", "smoke devils");
		cover("grotesque guardians", "gargoyles");
		cover("sarachnis", "spiders");
		cover("kalphite queen", "kalphites");
		cover("dagannoth rex", "dagannoth", "dagannoth kings");
		cover("dagannoth prime", "dagannoth", "dagannoth kings");
		cover("dagannoth supreme", "dagannoth", "dagannoth kings");
		cover("tztok-jad", "tzhaar");
		cover("tormented demon", "greater demons");
		cover("araxxor", "araxytes", "spiders");
		cover("amoxliatl", "lesser nagua");
		cover("skotizo", "black demons", "greater demons");
		cover("callisto", "bears");
		cover("artio", "bears");
		cover("venenatis", "spiders");
		cover("spindel", "spiders");
		cover("vet'ion", "skeletons");
		cover("scorpia", "scorpions");
		cover("demonic gorilla", "black demons", "monkeys");
		cover("greater nechryael", "nechryael");
		cover("lizardman shaman", "lizardmen");
		cover("rune dragon", "metal dragons");
		cover("adamant dragon", "metal dragons");
		cover("brutal black dragon", "black dragons");
		cover("kalphite soldier", "kalphites");
		cover("ammonite crab", "crabs");
		cover("sand crab", "crabs");
		cover("rock crab", "crabs");
	}

	private final Mode mode;
	private final String task;

	private SlayerTask(Mode mode, String task)
	{
		this.mode = mode;
		this.task = task == null || task.isEmpty() ? null : normal(task);
	}

	/** The assumption for a mode, with the player's current task name (or null when they have none). */
	public static SlayerTask of(Mode mode, String currentTask)
	{
		if (mode == Mode.ALWAYS)
		{
			return ALWAYS;
		}
		if (mode == Mode.NEVER)
		{
			return NEVER;
		}
		return new SlayerTask(Mode.SMART, currentTask);
	}

	public Mode getMode()
	{
		return mode;
	}

	/** The current task, lower case, or null. */
	public String getTask()
	{
		return task;
	}

	/** Whether the slayer helmet's bonus counts against this target. */
	public boolean covers(Target target)
	{
		if (target == null || !target.isSlayer() || mode == Mode.NEVER)
		{
			return false;
		}
		if (mode == Mode.ALWAYS || "Slayer".equals(target.getGroup()))
		{
			return true;
		}
		return task != null && taskCovers(task, target.getName());
	}

	/** Whether a task, by its name in the game, covers a monster by its name. */
	static boolean taskCovers(String task, String monster)
	{
		String t = normal(task);
		String m = normal(monster);
		if (t.equals(m))
		{
			return true;
		}
		return COVERED_BY.getOrDefault(m, Collections.emptySet()).contains(t);
	}

	/** Lower case, without "The" or a plural "s", so "The Abyssal Sire" and "Hill Giants" match their monsters. */
	static String normal(String name)
	{
		String s = name.toLowerCase(Locale.ROOT).trim();
		if (s.startsWith("the "))
		{
			s = s.substring(4);
		}
		if (s.endsWith("s") && !s.endsWith("ss"))
		{
			s = s.substring(0, s.length() - 1);
		}
		return s;
	}

	private static void cover(String monster, String... tasks)
	{
		Set<String> set = COVERED_BY.computeIfAbsent(normal(monster), k -> new HashSet<>());
		for (String task : tasks)
		{
			set.add(normal(task));
		}
	}

	@Override
	public boolean equals(Object o)
	{
		return o instanceof SlayerTask && ((SlayerTask) o).mode == mode
			&& (task == null ? ((SlayerTask) o).task == null : task.equals(((SlayerTask) o).task));
	}

	@Override
	public int hashCode()
	{
		return mode.hashCode() * 31 + (task == null ? 0 : task.hashCode());
	}

	@Override
	public String toString()
	{
		return mode + (task == null ? "" : ":" + task);
	}
}

