package com.codex.gearroadmap.data;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * The bundled tables: every combat-relevant piece of equipment, the catalogue of
 * upgrades worth recommending, the attack styles of each weapon category and the
 * monsters a roadmap can aim at.
 */
public final class RoadmapData
{
	private static final String RESOURCE = "/com/codex/gearroadmap/gear-roadmap.json";

	/** What a weapon category offers: an attack type ("stab", "ranged", "magic"...) and a stance. */
	public static final class Style
	{
		private final String type;
		private final String stance;

		public Style(String type, String stance)
		{
			this.type = type;
			this.stance = stance;
		}

		public String getType()
		{
			return type;
		}

		public String getStance()
		{
			return stance;
		}
	}

	private static final class Raw
	{
		Map<String, List<List<String>>> styles;
		List<List<Integer>> ammo;
		List<Gear> gear;
		List<CatalogueEntry> catalogue;
		List<Target> targets;
	}

	private final Map<Integer, Gear> byId = new HashMap<>();
	private final Map<String, Gear> byName = new HashMap<>();
	private final Map<String, List<Style>> styles = new HashMap<>();
	private final Map<String, CatalogueEntry> catalogue = new LinkedHashMap<>();
	private final List<Target> targets;
	private final List<Gear> gear;
	private final List<Set<Integer>> ammo = new ArrayList<>();

	private RoadmapData(Raw raw)
	{
		gear = raw.gear == null ? Collections.emptyList() : raw.gear;
		for (Gear g : gear)
		{
			byName.put(g.key(), g);
			for (int id : g.getIds())
			{
				byId.putIfAbsent(id, g);
			}
		}
		if (raw.styles != null)
		{
			for (Map.Entry<String, List<List<String>>> e : raw.styles.entrySet())
			{
				List<Style> list = new ArrayList<>();
				for (List<String> pair : e.getValue())
				{
					if (pair.size() >= 2)
					{
						list.add(new Style(pair.get(0), pair.get(1)));
					}
				}
				styles.put(e.getKey(), list);
			}
		}
		if (raw.catalogue != null)
		{
			for (CatalogueEntry entry : raw.catalogue)
			{
				Gear g = byName.get(entry.getName().toLowerCase(Locale.ROOT));
				if (g != null)
				{
					entry.setGear(g);
					catalogue.put(g.key(), entry);
				}
			}
		}
		if (raw.ammo != null)
		{
			for (List<Integer> list : raw.ammo)
			{
				ammo.add(list == null ? Collections.emptySet() : new HashSet<>(list));
			}
		}
		targets = raw.targets == null ? Collections.emptyList() : raw.targets;
	}

	public static RoadmapData load(Gson gson) throws IOException
	{
		try (InputStream in = RoadmapData.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("Missing " + RESOURCE);
			}
			return read(gson, new InputStreamReader(in, StandardCharsets.UTF_8));
		}
	}

	public static RoadmapData read(Gson gson, Reader reader) throws IOException
	{
		try
		{
			Raw raw = gson.fromJson(reader, Raw.class);
			if (raw == null)
			{
				throw new IOException("Empty gear data");
			}
			return new RoadmapData(raw);
		}
		catch (JsonParseException e)
		{
			throw new IOException(e);
		}
	}

	/** The piece an item id counts as, or null when it is not combat gear. */
	public Gear gear(int itemId)
	{
		return byId.get(itemId);
	}

	/**
	 * The ammunition ids a weapon fires: null when the weapon is not a ranged weapon that
	 * cares, empty when it fires no ammunition (a blowpipe or crystal bow).
	 */
	public Set<Integer> ammoFor(Gear weapon)
	{
		int list = weapon == null ? -1 : weapon.ammoList();
		return list < 0 || list >= ammo.size() ? null : ammo.get(list);
	}

	public Gear named(String name)
	{
		return name == null ? null : byName.get(name.toLowerCase(Locale.ROOT));
	}

	public List<Gear> allGear()
	{
		return gear;
	}

	public List<Style> styles(String category)
	{
		List<Style> list = styles.get(category);
		return list == null ? styles.getOrDefault("Unarmed", Collections.emptyList()) : list;
	}

	public CatalogueEntry entry(Gear gear)
	{
		return gear == null ? null : catalogue.get(gear.key());
	}

	public List<CatalogueEntry> catalogue()
	{
		return new ArrayList<>(catalogue.values());
	}

	public List<Target> targets()
	{
		return targets;
	}

	public Target target(String name)
	{
		for (Target t : targets)
		{
			if (t.getName().equalsIgnoreCase(name))
			{
				return t;
			}
		}
		return null;
	}
}

package com.codex.gearroadmap.data;

import java.util.Collections;
import java.util.List;
import java.util.Locale;

/** A monster the player can aim their gear at, with the stats that defend against each attack. */
public final class Target
{
	public static final int D_STAB = 0;
	public static final int D_SLASH = 1;
	public static final int D_CRUSH = 2;
	public static final int D_MAGIC = 3;
	public static final int D_LIGHT = 4;
	public static final int D_STANDARD = 5;
	public static final int D_HEAVY = 6;

	private int id;
	private String name;
	private String group;
	private int hp;
	private int def;
	private int mag;
	private int mb;
	private int[] d;
	private int size;
	private List<String> attr;
	private boolean slayer;
	private List<Object> weak;
	private List<String> only;
	private boolean wild;
	private int fa;

	public Target()
	{
	}

	public Target(String name, String group, int hp, int def, int magic, int[] defensive, int size, List<String> attributes, boolean slayer)
	{
		this.name = name;
		this.group = group;
		this.hp = hp;
		this.def = def;
		this.mag = magic;
		this.d = defensive;
		this.size = size;
		this.attr = attributes;
		this.slayer = slayer;
	}

	public int getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	/** Boss, Slayer or Training. */
	public String getGroup()
	{
		return group;
	}

	public int getHp()
	{
		return hp;
	}

	public int getDefence()
	{
		return def;
	}

	public int getMagic()
	{
		return mag;
	}

	public int getMagicAttack()
	{
		return mb;
	}

	public int defensive(int type)
	{
		return d == null ? 0 : d[type];
	}

	public int getSize()
	{
		return Math.max(1, size);
	}

	public boolean is(String attribute)
	{
		return attr != null && attr.contains(attribute);
	}

	public List<String> getAttributes()
	{
		return attr == null ? Collections.emptyList() : attr;
	}

	public boolean isSlayer()
	{
		return slayer;
	}

	/** Whether it is fought in the Wilderness, where revenant weapons are stronger. */
	public boolean isWilderness()
	{
		return wild;
	}

	/** Armour taken off every melee and ranged hit that lands, or added when below zero. */
	public int getFlatArmour()
	{
		return fa;
	}

	/** Percent of a demonbane weapon's bonus this demon takes: Duke Sucellus resists, Yama is weak to it. */
	public int demonbaneVulnerability()
	{
		if ("Duke Sucellus".equals(name))
		{
			return 70;
		}
		return "Yama".equals(name) ? 120 : 100;
	}

	/** Bosses, Slayer creatures or training spots. */
	public boolean isBoss()
	{
		return "Boss".equals(group);
	}

	/** The element this monster takes extra magic damage from, or null. */
	public String weakness()
	{
		return weak == null || weak.size() < 2 || weak.get(0) == null ? null : weak.get(0).toString().toLowerCase(Locale.ROOT);
	}

	/** Percent of extra accuracy and damage the weak element gets. */
	public int weaknessSeverity()
	{
		if (weak == null || weak.size() < 2 || !(weak.get(1) instanceof Number))
		{
			return 0;
		}
		return ((Number) weak.get(1)).intValue();
	}

	@Override
	public String toString()
	{
		return name;
	}

	/** Whether the target can be hurt with this kind of attack: melee, ranged or magic. */
	public boolean allows(String kind)
	{
		return only == null || only.contains(kind.toLowerCase());
	}
}

package com.codex.gearroadmap.overlay;

import com.codex.gearroadmap.ui.Sigil;
import com.codex.gearroadmap.ui.Theme;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A gilt plaque that rises in the game view when the player gets an upgrade from their
 * road: the item, the damage it adds against the aimed target and what comes next. It
 * draws a view the plugin prepares, so rendering never touches game state.
 */
public class UpgradePlaque extends Overlay
{
	private static final int WIDTH = 228;
	private static final int PAD = 9;
	private static final int ICON = 40;
	private static final long FADE_MS = 450;

	/** What the plaque shows. */
	public static final class View
	{
		final String heading;
		final String name;
		final String gain;
		final String next;
		final Color color;
		final BufferedImage icon;
		final long shownAt;
		final long durationMs;

		public View(String heading, String name, String gain, String next, Color color, BufferedImage icon,
			long shownAt, long durationMs)
		{
			this.heading = heading;
			this.name = name;
			this.gain = gain;
			this.next = next;
			this.color = color;
			this.icon = icon;
			this.shownAt = shownAt;
			this.durationMs = durationMs;
		}
	}

	private volatile View view;

	public UpgradePlaque()
	{
		setPosition(OverlayPosition.TOP_CENTER);
	}

	public void show(View view)
	{
		this.view = view;
	}

	public void clear()
	{
		view = null;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		View v = view;
		if (v == null)
		{
			return null;
		}
		long age = System.currentTimeMillis() - v.shownAt;
		if (age > v.durationMs)
		{
			view = null;
			return null;
		}
		float alpha = (float) Math.min(1, Math.min(age / (double) FADE_MS, (v.durationMs - age) / (double) FADE_MS));
		Composite old = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0, alpha)));
		Theme.smooth(g);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		int lines = 2 + (v.gain == null ? 0 : 1) + (v.next == null ? 0 : 1);
		int textHeight = small.getHeight() + bold.getHeight() + (lines - 2) * (small.getHeight() + 1);
		int height = PAD * 2 + Math.max(ICON, textHeight);
		Color tint = v.color;

		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, WIDTH - 1, height - 1, 12, 12);
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 238), 0, height, Theme.alpha(Theme.INK_DEEP, 238)));
		g.fill(shape);
		double beat = 0.5 + 0.5 * Math.sin(age / 220.0);
		g.setStroke(new BasicStroke(3f));
		g.setColor(Theme.alpha(tint, (int) (40 + beat * 70)));
		g.draw(shape);
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(tint, 200));
		g.draw(shape);

		// The item sits in a lit well.
		int wellX = PAD;
		int wellY = (height - ICON) / 2;
		g.setPaint(new RadialGradientPaint(wellX + ICON / 2f, wellY + ICON / 2f, ICON / 2f,
			new float[]{0f, 1f}, new Color[]{Theme.alpha(tint, 110), Theme.alpha(Theme.INK_DEEP, 220)}));
		g.fill(new Ellipse2D.Float(wellX, wellY, ICON, ICON));
		g.setColor(Theme.alpha(tint, 170));
		g.draw(new Ellipse2D.Float(wellX, wellY, ICON, ICON));
		if (v.icon != null)
		{
			g.drawImage(v.icon, wellX + (ICON - v.icon.getWidth()) / 2, wellY + (ICON - v.icon.getHeight()) / 2, null);
		}
		else
		{
			Sigil.paint(g, wellX + 8, wellY + 8, ICON - 16);
		}

		int x = PAD + ICON + 9;
		int width = WIDTH - x - PAD;
		int y = PAD + Math.max(0, (Math.max(ICON, textHeight) - textHeight) / 2);
		g.setFont(Theme.small());
		shadow(g, v.heading, x, y + small.getAscent(), tint);
		y += small.getHeight();
		g.setFont(Theme.title());
		shadow(g, clip(v.name, bold, width), x, y + bold.getAscent(), Theme.GOLD_BRIGHT);
		y += bold.getHeight();
		g.setFont(Theme.small());
		if (v.gain != null)
		{
			shadow(g, clip(v.gain, small, width), x, y + small.getAscent(), Theme.TEAL);
			y += small.getHeight() + 1;
		}
		if (v.next != null)
		{
			shadow(g, clip(v.next, small, width), x, y + small.getAscent(), Theme.TEXT_MUTED);
		}
		g.setComposite(old);
		return new Dimension(WIDTH, height);
	}

	private static void shadow(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private static String clip(String text, FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		String ellipsis = "...";
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + ellipsis) > width)
		{
			end--;
		}
		return text.substring(0, end) + ellipsis;
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private final String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Report;
import com.codex.gearroadmap.core.Result;
import com.codex.gearroadmap.core.Roadmap;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.geom.Path2D;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/**
 * The crest at the top of the panel: the dial, the player and their target, and three
 * ledgers for the kill time now, how much faster the road ends, and the coins to spend.
 */
public class Crest extends JPanel
{
	private final DpsDial dial = new DpsDial(74);
	private final JLabel title = Ui.label("Gear Roadmap", Theme.title(), Theme.GOLD_BRIGHT);
	private final JLabel target = Ui.label("Log in to plan your gear", Theme.small(), Theme.TEXT_MUTED);
	private final Ledger kill = new Ledger("Kill time");
	private final Ledger road = new Ledger("Road ahead");
	private final Ledger coins = new Ledger("Coins");
	private Color glow = Theme.GOLD_DIM;

	public Crest()
	{
		super(new BorderLayout(10, 0));
		setOpaque(false);
		setBorder(new EmptyBorder(12, 10, 12, 10));

		JPanel dialHolder = new JPanel(new BorderLayout());
		dialHolder.setOpaque(false);
		dialHolder.add(dial, BorderLayout.NORTH);
		add(dialHolder, BorderLayout.WEST);

		JPanel right = new JPanel();
		right.setOpaque(false);
		right.setLayout(new BoxLayout(right, BoxLayout.Y_AXIS));
		title.setAlignmentX(LEFT_ALIGNMENT);
		target.setAlignmentX(LEFT_ALIGNMENT);
		right.add(title);
		right.add(target);
		JPanel ledgers = new JPanel(new GridLayout(3, 1, 0, 2));
		ledgers.setOpaque(false);
		ledgers.setBorder(new EmptyBorder(4, 0, 0, 0));
		ledgers.add(kill);
		ledgers.add(road);
		ledgers.add(coins);
		ledgers.setAlignmentX(LEFT_ALIGNMENT);
		right.add(ledgers);
		add(right, BorderLayout.CENTER);
		dial.set("-", 0, 0, Theme.GOLD, false);
	}

	public void update(Report report, String playerName)
	{
		Roadmap map = report.getRoadmap();
		if (!report.isLoggedIn() || map == null)
		{
			title.setText(playerName == null ? "Gear Roadmap" : playerName);
			target.setText(report.isLoggedIn() ? "Reading your gear..." : "Log in to plan your gear");
			target.setForeground(Theme.TEXT_MUTED);
			dial.set("-", 0, 0, Theme.GOLD, true);
			kill.set("-", Theme.TEXT);
			road.set("-", Theme.TEXT);
			coins.set("-", Theme.TEXT);
			glow = Theme.GOLD_DIM;
			repaint();
			return;
		}
		Result now = map.getNow().best().getResult();
		Color color = Theme.kind(now.getKind());
		title.setText(playerName == null ? "Gear Roadmap" : playerName);
		target.setText("vs " + map.getTarget().getName() + (now.getKind() == null ? "" : "  ·  " + now.getKind()));
		target.setForeground(Theme.mix(Theme.TEXT_MUTED, color, 0.55));
		double end = map.finalDps();
		double affordable = now.getDps();
		for (Roadmap.Step step : map.getPath())
		{
			if (step.isAffordable())
			{
				affordable = step.getOption().getAfter().dps();
			}
		}
		dial.set(Format.dps(now.getDps()), end <= 0 ? 0 : now.getDps() / end, end <= 0 ? 0 : affordable / end, color, true);
		kill.set(Format.time(now.secondsToKill(map.getTarget())), Theme.TEXT);
		road.set(map.getPath().isEmpty() ? "Complete" : Format.share(end / Math.max(0.01, now.getDps()) - 1), Theme.TEAL);
		if (report.isIronman())
		{
			coins.label("Road cost");
			coins.set(map.getPath().isEmpty() ? "-" : Format.coins(map.getPath().get(map.getPath().size() - 1).getSpent()), Theme.GOLD);
		}
		else
		{
			coins.label("Coins");
			coins.set(Format.coins(map.getCoins()).replace("Free", "0"), Theme.GOLD);
		}
		glow = Theme.mix(Theme.GOLD_DIM, color, 0.4);
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, glow, 0.2), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// Gilt rule along the bottom with a small diamond at its centre.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
		super.paintComponent(graphics);
	}

	/** One labelled value. */
	private static final class Ledger extends JPanel
	{
		private final JLabel value = Ui.label("-", Theme.small(), Theme.TEXT);
		private final JLabel name;

		Ledger(String label)
		{
			super(new BorderLayout());
			setOpaque(false);
			name = Ui.label(label, Theme.small(), Theme.TEXT_MUTED);
			add(name, BorderLayout.WEST);
			add(value, BorderLayout.EAST);
			setPreferredSize(new Dimension(10, 15));
		}

		void label(String text)
		{
			name.setText(text);
		}

		void set(String text, Color color)
		{
			value.setText(text);
			value.setForeground(color);
		}
	}
}

package com.codex.gearroadmap.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import javax.swing.JComponent;

/**
 * The crest's dial: today's damage per second in the middle, and an arc showing how far
 * along the road that is, from nothing to the damage at the road's end. A faint second
 * arc marks what the player's coins already reach.
 */
public class DpsDial extends JComponent
{
	private final int diameter;
	private final Animator now = new Animator(this);
	private final Animator reach = new Animator(this);
	private String value = "-";
	private Color color = Theme.GOLD;

	public DpsDial(int diameter)
	{
		this.diameter = diameter;
		Dimension d = new Dimension(diameter, diameter);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setOpaque(false);
	}

	/**
	 * @param share today's damage as a share of the road's end
	 * @param affordable the damage the player's coins reach, as the same share
	 */
	public void set(String value, double share, double affordable, Color color, boolean animate)
	{
		this.value = value;
		this.color = color;
		now.set(clamp(share), animate);
		reach.set(clamp(Math.max(share, affordable)), animate);
	}

	private static double clamp(double v)
	{
		return Double.isNaN(v) ? 0 : Math.max(0, Math.min(1, v));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		float thickness = 6f;
		float inset = thickness / 2 + 2;
		float size = diameter - inset * 2;

		g.setPaint(new RadialGradientPaint(diameter / 2f, diameter / 2f, size / 2f, new float[]{0f, 1f},
			new Color[]{Theme.alpha(color, 46), Theme.alpha(Theme.INK_DEEP, 0)}));
		g.fill(new Ellipse2D.Float(inset, inset, size, size));

		// A 270 degree track open at the bottom, like a gauge.
		float start = 225;
		float sweep = -270;
		g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.alpha(Theme.STROKE, 210));
		g.draw(new Arc2D.Float(inset, inset, size, size, start, sweep, Arc2D.OPEN));
		double reached = reach.get();
		if (reached > now.get() + 0.005)
		{
			g.setColor(Theme.alpha(Theme.GOLD, 70));
			g.draw(new Arc2D.Float(inset, inset, size, size, start, (float) (sweep * reached), Arc2D.OPEN));
		}
		double value = now.get();
		if (value > 0)
		{
			int segments = Math.max(1, (int) Math.ceil(value * 60));
			double step = sweep * value / segments;
			for (int i = 0; i < segments; i++)
			{
				double t = (i + 1) / (double) segments * value;
				g.setColor(Theme.mix(Theme.GOLD_DIM, color, Math.min(1, t * 1.3)));
				g.draw(new Arc2D.Double(inset, inset, size, size, start + i * step, step - (i < segments - 1 ? 0.6 : 0), Arc2D.OPEN));
			}
		}
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 90));
		g.draw(new Ellipse2D.Float(0.5f, 0.5f, diameter - 1, diameter - 1));

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		int y = diameter / 2 + bold.getAscent() / 2 - 4;
		ProgressRing.drawShadowed(g, this.value, (diameter - bold.stringWidth(this.value)) / 2, y, Theme.TEXT);
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		ProgressRing.drawShadowed(g, "DPS", (diameter - small.stringWidth("DPS")) / 2, y + small.getAscent() + 1, Theme.TEXT_MUTED);
		g.dispose();
	}
}

package com.codex.gearroadmap.ui;

/** Coins, damage and times in the short forms the panel uses. */
public final class Format
{
	private Format()
	{
	}

	/** "850", "60k", "1.4M", "1.6B"; "Free" for nothing at all. */
	public static String coins(long gp)
	{
		if (gp <= 0)
		{
			return "Free";
		}
		if (gp < 1_000)
		{
			return String.valueOf(gp);
		}
		if (gp < 100_000)
		{
			return trim(gp / 1_000.0) + "k";
		}
		if (gp < 1_000_000)
		{
			return Math.round(gp / 1_000.0) + "k";
		}
		if (gp < 1_000_000_000)
		{
			return trim(gp / 1_000_000.0) + "M";
		}
		return trim(gp / 1_000_000_000.0) + "B";
	}

	private static String trim(double value)
	{
		if (value >= 100)
		{
			return String.valueOf(Math.round(value));
		}
		String text = String.format("%.1f", value);
		return text.endsWith(".0") ? text.substring(0, text.length() - 2) : text;
	}

	/** Damage per second to two places. */
	public static String dps(double dps)
	{
		return String.format("%.2f", Math.max(0, dps));
	}

	/** "+0.42", for a gain. */
	public static String gain(double dps)
	{
		return "+" + dps(dps);
	}

	/** "+14%", with "<1%" for the smallest gains. */
	public static String share(double share)
	{
		if (share <= 0)
		{
			return "+0%";
		}
		if (share < 0.01)
		{
			return "+<1%";
		}
		return "+" + Math.round(share * 100) + "%";
	}

	/** Whole percent. */
	public static String percent(double share)
	{
		return Math.round(Math.max(0, Math.min(1, share)) * 100) + "%";
	}

	/** "48s", "1m 32s", "12m"; "-" when it cannot be done. */
	public static String time(double seconds)
	{
		if (Double.isNaN(seconds) || Double.isInfinite(seconds) || seconds <= 0)
		{
			return "-";
		}
		long s = Math.round(seconds);
		if (s < 60)
		{
			return s + "s";
		}
		long m = s / 60;
		long r = s % 60;
		if (m >= 10 || r == 0)
		{
			return m + "m";
		}
		return m + "m " + r + "s";
	}

	/** What each point of DPS costs on this upgrade: "85k per DPS". */
	public static String value(long cost, double gain)
	{
		if (cost <= 0 || gain <= 0)
		{
			return "";
		}
		return coins(Math.round(cost / gain)) + " per DPS";
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Loadout;
import com.codex.gearroadmap.data.Gear;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.swing.JComponent;

/**
 * The loadout laid out like the game's worn equipment screen. Pieces new to the player
 * glow teal; empty slots show a faint engraving of what belongs there.
 */
public class GearGrid extends JComponent
{
	private static final int TILE_W = 38;
	private static final int TILE_H = 34;
	private static final int GAP = 6;
	/** Column and row of each slot, in the order of Gear's slot numbers. */
	private static final int[][] CELLS = {
		{1, 0}, {0, 1}, {1, 1}, {2, 1}, {0, 2}, {1, 2}, {2, 2}, {1, 3}, {0, 4}, {1, 4}, {2, 4},
	};
	private static final String[] ENGRAVING = {"Hd", "Cp", "Nk", "Am", "Wp", "Bd", "Sh", "Lg", "Gl", "Bt", "Rg"};

	private final Loadout loadout;
	private final Set<Gear> fresh;
	private final Color accent;
	private final Map<Integer, BufferedImage> images = new HashMap<>();
	private int hover = -1;

	public GearGrid(Loadout loadout, Set<Gear> fresh, Color accent, ItemIcons icons)
	{
		this.loadout = loadout;
		this.fresh = fresh == null ? Collections.emptySet() : fresh;
		this.accent = accent;
		setPreferredSize(new Dimension(10, 5 * TILE_H + 4 * GAP + 4));
		setOpaque(false);
		for (int slot = 0; slot < Gear.SLOTS; slot++)
		{
			Gear g = loadout.get(slot);
			if (g != null && icons != null)
			{
				images.put(slot, icons.icon(g.getId(), this::repaint));
			}
		}
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int slot = slotAt(e.getX(), e.getY());
				if (slot != hover)
				{
					hover = slot;
					Gear g = slot < 0 ? null : loadout.get(slot);
					setToolTipText(slot < 0 ? null : g == null ? Gear.SLOT_NAMES[slot] + ": empty" : g.getName());
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	private int left()
	{
		return (getWidth() - (3 * TILE_W + 2 * GAP)) / 2;
	}

	private int slotAt(int x, int y)
	{
		for (int slot = 0; slot < Gear.SLOTS; slot++)
		{
			int tx = left() + CELLS[slot][0] * (TILE_W + GAP);
			int ty = 2 + CELLS[slot][1] * (TILE_H + GAP);
			if (x >= tx && x < tx + TILE_W && y >= ty && y < ty + TILE_H)
			{
				return slot;
			}
		}
		return -1;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int left = left();

		// Faint gilt threads joining the slots, like the game's equipment frame.
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 70));
		int cx = left + TILE_W + GAP + TILE_W / 2;
		g.drawLine(cx, 2 + TILE_H, cx, 2 + 4 * (TILE_H + GAP));
		int midY = 2 + 2 * (TILE_H + GAP) + TILE_H / 2;
		g.drawLine(left + TILE_W, midY, left + 2 * (TILE_W + GAP), midY);
		int capeY = 2 + (TILE_H + GAP) + TILE_H / 2;
		g.drawLine(left + TILE_W, capeY, left + 2 * (TILE_W + GAP), capeY);

		for (int slot = 0; slot < Gear.SLOTS; slot++)
		{
			int tx = left + CELLS[slot][0] * (TILE_W + GAP);
			int ty = 2 + CELLS[slot][1] * (TILE_H + GAP);
			drawTile(g, slot, tx, ty);
		}
		g.dispose();
	}

	private void drawTile(Graphics2D g, int slot, int x, int y)
	{
		Gear gear = loadout.get(slot);
		boolean isFresh = gear != null && fresh.contains(gear);
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, TILE_W - 1, TILE_H - 1, 8, 8);
		Color top = gear == null ? Theme.INK_DEEP : Theme.mix(Theme.CARD_TOP, isFresh ? Theme.TEAL : accent, 0.16);
		g.setPaint(new GradientPaint(x, y, top, x, y + TILE_H, gear == null ? Theme.INK_DEEP : Theme.CARD));
		g.fill(shape);
		Color rim = isFresh ? Theme.TEAL : gear == null ? Theme.STROKE_SOFT : Theme.alpha(Theme.GOLD, 150);
		if (hover == slot)
		{
			rim = Theme.GOLD_BRIGHT;
		}
		g.setStroke(new BasicStroke(isFresh ? 1.4f : 1f));
		g.setColor(rim);
		g.draw(shape);
		if (gear == null)
		{
			g.setFont(Theme.small());
			FontMetrics fm = g.getFontMetrics();
			String text = ENGRAVING[slot];
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(text, x + (TILE_W - fm.stringWidth(text)) / 2, y + (TILE_H + fm.getAscent()) / 2 - 1);
			return;
		}
		BufferedImage image = images.get(slot);
		if (image != null)
		{
			Composite old = g.getComposite();
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 1f));
			g.drawImage(image, x + (TILE_W - image.getWidth()) / 2, y + (TILE_H - image.getHeight()) / 2, null);
			g.setComposite(old);
		}
		g.setColor(Theme.alpha(Color.WHITE, 16));
		g.drawLine(x + 5, y + 1, x + TILE_W - 5, y + 1);
	}
}

