package com.codex.gearroadmap.ui;

import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A slim rounded bar that fills with the same ember-to-teal ramp as the rings. */
public class ProgressBar extends JComponent
{
	private final Animator animator = new Animator(this);
	private boolean complete;

	public ProgressBar(int height)
	{
		setPreferredSize(new Dimension(10, height));
		setMinimumSize(new Dimension(10, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		setOpaque(false);
	}

	public void setProgress(double progress, boolean complete, boolean animate)
	{
		this.complete = complete;
		animator.set(Math.max(0, Math.min(1, progress)), animate);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float arc = h;
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(0, 0, w, h, arc, arc));
		double value = animator.get();
		if (value > 0)
		{
			float fill = (float) Math.max(h, w * value);
			if (complete)
			{
				g.setColor(Theme.GREEN);
			}
			else
			{
				g.setPaint(new GradientPaint(0, 0, Theme.progressColor(0), w, 0, Theme.progressColor(1)));
			}
			g.fill(new RoundRectangle2D.Float(0, 0, fill, h, arc, arc));
			g.setColor(Theme.alpha(java.awt.Color.WHITE, 40));
			g.drawLine(Math.round(arc / 2), 0, Math.round(fill - arc / 2), 0);
		}
		g.setColor(Theme.alpha(Theme.STROKE, 160));
		g.draw(new RoundRectangle2D.Float(0, 0, w - 1, h - 1, arc, arc));
		g.dispose();
	}
}

package com.codex.gearroadmap.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import javax.swing.JComponent;

/** A gilded progress ring with the percentage set in the game's bold font. */
public class ProgressRing extends JComponent
{
	private final int diameter;
	private final float thickness;
	private final Animator animator = new Animator(this);
	private String caption;
	private boolean complete;

	public ProgressRing(int diameter, float thickness)
	{
		this.diameter = diameter;
		this.thickness = thickness;
		Dimension size = new Dimension(diameter, diameter);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
		setOpaque(false);
	}

	public void setProgress(double progress, boolean complete, boolean animate)
	{
		this.complete = complete;
		animator.set(Math.max(0, Math.min(1, progress)), animate);
	}

	/** A small line under the percentage, for rings large enough to hold it. */
	public void setCaption(String caption)
	{
		this.caption = caption;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		double value = animator.get();
		float inset = thickness / 2f + 1;
		float size = diameter - inset * 2;

		// Inner well: a faint radial glow tinted by progress.
		Color glow = complete ? Theme.GREEN : Theme.progressColor(value);
		float r = size / 2f;
		g.setPaint(new RadialGradientPaint(diameter / 2f, diameter / 2f, r,
			new float[]{0f, 1f}, new Color[]{Theme.alpha(glow, 40), Theme.alpha(Theme.INK_DEEP, 0)}));
		g.fill(new Ellipse2D.Float(inset, inset, size, size));

		g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.alpha(Theme.STROKE, 200));
		g.draw(new Arc2D.Float(inset, inset, size, size, 0, 360, Arc2D.OPEN));

		if (value > 0)
		{
			g.setStroke(new BasicStroke(thickness, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			// Draw the arc in short segments so its colour can travel from ember to teal.
			int segments = Math.max(1, (int) Math.ceil(value * 72));
			double sweep = value * 360 / segments;
			for (int i = 0; i < segments; i++)
			{
				double t = (i + 1) / (double) segments * value;
				g.setColor(complete ? Theme.GREEN : Theme.progressColor(t));
				g.draw(new Arc2D.Double(inset, inset, size, size, 90 - i * sweep, -sweep - (i < segments - 1 ? 0.6 : 0), Arc2D.OPEN));
			}
		}

		// Fine gold rim outside the track.
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 90));
		g.draw(new Ellipse2D.Float(0.5f, 0.5f, diameter - 1, diameter - 1));

		g.setFont(diameter >= 48 ? Theme.title() : Theme.small());
		String text = Math.round(value * 100) + "%";
		FontMetrics fm = g.getFontMetrics();
		if (complete)
		{
			drawCheck(g, diameter / 2f, diameter / 2f - (caption != null && diameter >= 60 ? 5 : 0), diameter * 0.16f);
			text = null;
		}
		int textY = diameter / 2 + fm.getAscent() / 2 - 2;
		if (caption != null && diameter >= 60)
		{
			textY -= 5;
		}
		if (text != null)
		{
			drawShadowed(g, text, (diameter - fm.stringWidth(text)) / 2, textY, Theme.TEXT);
		}

		if (caption != null && diameter >= 60)
		{
			g.setFont(Theme.small());
			FontMetrics small = g.getFontMetrics();
			drawShadowed(g, caption, (diameter - small.stringWidth(caption)) / 2, textY + small.getAscent() + 1, Theme.TEXT_MUTED);
		}
		g.dispose();
	}

	/** A drawn check mark, since the game fonts have no glyph for one. */
	static void drawCheck(Graphics2D g, float cx, float cy, float r)
	{
		java.awt.geom.Path2D check = new java.awt.geom.Path2D.Float();
		check.moveTo(cx - r, cy);
		check.lineTo(cx - r * 0.3f, cy + r * 0.7f);
		check.lineTo(cx + r, cy - r * 0.65f);
		g.setStroke(new BasicStroke(Math.max(1.6f, r * 0.32f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.GREEN);
		g.draw(check);
	}

	static void drawShadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Roadmap;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComponent;

/**
 * The road itself: damage per second climbing against coins spent. Each upgrade is a
 * waypoint carrying its item; the stretch the player's coins already cover is lit gold,
 * the rest waits in the dusk. Coins run on a square-root scale so cheap early steps are
 * not crushed against the left edge by one expensive leap at the end.
 */
public class RoadChart extends JComponent
{
	private static final int HEIGHT = 160;
	private static final int PAD_LEFT = 8;
	private static final int PAD_RIGHT = 12;
	private static final int PAD_TOP = 26;
	private static final int PAD_BOTTOM = 22;
	private static final int NODE = 20;

	private final Roadmap map;
	private final List<BufferedImage> icons = new ArrayList<>();
	private int hover = -1;

	public RoadChart(Roadmap map, ItemIcons icons)
	{
		this.map = map;
		setPreferredSize(new Dimension(10, HEIGHT));
		setOpaque(false);
		for (Roadmap.Step step : map.getPath())
		{
			this.icons.add(icons == null ? null : icons.icon(step.getOption().getIcon().getId(), this::repaint));
		}
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = nodeAt(e.getX(), e.getY());
				if (index != hover)
				{
					hover = index;
					setToolTipText(index < 0 ? null : tooltip(map.getPath().get(index)));
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	private static String tooltip(Roadmap.Step step)
	{
		Roadmap.Option o = step.getOption();
		return "<html><b>" + Ui.escape(o.getName()) + "</b><br>" + Format.gain(o.getGain()) + " DPS for " + Format.coins(o.getCost())
			+ "<br>" + Format.coins(step.getSpent()) + " spent by here</html>";
	}

	/**
	 * Where a coin total sits across the chart. A quarter of the distance follows the square root
	 * of the coins and the rest the step count, so dear steps late on still get room apart.
	 */
	private double x(long spent, double total, int w)
	{
		List<Roadmap.Step> path = map.getPath();
		int n = path.size();
		double t = 0;
		if (total > 0 && n > 0)
		{
			long before = 0;
			for (int k = 0; k < n; k++)
			{
				long after = path.get(k).getSpent();
				if (spent <= after || k == n - 1)
				{
					double a = blend(before, k, total, n);
					double b = blend(after, k + 1, total, n);
					double span = Math.sqrt(after / total) - Math.sqrt(before / total);
					double part = span <= 0 ? 1 : (Math.sqrt(Math.min(spent, after) / total) - Math.sqrt(before / total)) / span;
					t = a + (b - a) * Math.max(0, Math.min(1, part));
					break;
				}
				before = after;
			}
		}
		return PAD_LEFT + NODE / 2.0 + t * (w - PAD_LEFT - PAD_RIGHT - NODE);
	}

	private static double blend(long spent, int step, double total, int steps)
	{
		return 0.25 * Math.sqrt(spent / total) + 0.75 * step / steps;
	}

	private double y(double dps, double low, double high, int h)
	{
		double t = high <= low ? 0 : (dps - low) / (high - low);
		return h - PAD_BOTTOM - NODE / 2.0 - t * (h - PAD_TOP - PAD_BOTTOM - NODE);
	}

	private int nodeAt(int mx, int my)
	{
		List<Roadmap.Step> path = map.getPath();
		double total = path.isEmpty() ? 0 : path.get(path.size() - 1).getSpent();
		double low = map.getNow().dps();
		double high = map.finalDps();
		for (int i = 0; i < path.size(); i++)
		{
			double nx = x(path.get(i).getSpent(), total, getWidth());
			double ny = y(path.get(i).getOption().getAfter().dps(), low, high, getHeight());
			if (Math.abs(mx - nx) <= NODE / 2.0 + 1 && Math.abs(my - ny) <= NODE / 2.0 + 1)
			{
				return i;
			}
		}
		return -1;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D frame = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, h, Theme.INK_DEEP));
		g.fill(frame);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(frame);

		List<Roadmap.Step> path = map.getPath();
		double now = map.getNow().dps();
		double end = map.finalDps();
		long total = path.isEmpty() ? 0 : path.get(path.size() - 1).getSpent();
		g.setClip(frame);

		// Faint contour lines, like a surveyor's map.
		g.setStroke(new BasicStroke(1f));
		for (int i = 1; i < 4; i++)
		{
			int gy = PAD_TOP + NODE / 2 + i * (h - PAD_TOP - PAD_BOTTOM - NODE) / 4;
			g.setColor(Theme.alpha(Theme.STROKE, 70));
			g.drawLine(PAD_LEFT, gy, w - PAD_RIGHT, gy);
		}

		int n = path.size();
		double[] xs = new double[n + 1];
		double[] ys = new double[n + 1];
		xs[0] = x(0, total, w);
		ys[0] = y(now, now, end, h);
		for (int i = 0; i < n; i++)
		{
			xs[i + 1] = x(path.get(i).getSpent(), total, w);
			ys[i + 1] = y(path.get(i).getOption().getAfter().dps(), now, end, h);
		}

		// Where the player's coins run out.
		double reach = map.getCoins() >= total ? xs[n] : x(map.getCoins(), total, w);
		if (n > 0)
		{
			Path2D area = smooth(xs, ys);
			area.lineTo(xs[n], h - PAD_BOTTOM + 4);
			area.lineTo(xs[0], h - PAD_BOTTOM + 4);
			area.closePath();
			g.setPaint(new GradientPaint(0, PAD_TOP, Theme.alpha(Theme.GOLD, 46), 0, h - PAD_BOTTOM, Theme.alpha(Theme.GOLD, 0)));
			g.fill(area);

			Path2D line = smooth(xs, ys);
			g.setStroke(new BasicStroke(5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(Theme.alpha(Theme.INK_DEEP, 220));
			g.draw(line);
			g.setStroke(new BasicStroke(2.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1f, new float[]{5f, 4f}, 0));
			g.setColor(Theme.alpha(Theme.GOLD_DIM, 170));
			g.draw(line);
			// The covered stretch is drawn solid over the dashed road.
			Graphics2D lit = (Graphics2D) g.create();
			lit.clipRect(0, 0, (int) Math.ceil(reach), h);
			lit.setStroke(new BasicStroke(2.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			lit.setPaint(new GradientPaint((float) xs[0], 0, Theme.GOLD, (float) Math.max(xs[0] + 1, reach), 0, Theme.GOLD_BRIGHT));
			lit.draw(line);
			lit.dispose();

			if (map.getCoins() > 0 && map.getCoins() < total)
			{
				g.setStroke(new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 1f, new float[]{2f, 3f}, 0));
				g.setColor(Theme.alpha(Theme.TEAL, 170));
				g.drawLine((int) reach, PAD_TOP - 6, (int) reach, h - PAD_BOTTOM + 2);
				g.setFont(Theme.small());
				FontMetrics fm = g.getFontMetrics();
				String label = "Your coins";
				int lx = (int) Math.min(w - PAD_RIGHT - fm.stringWidth(label), Math.max(PAD_LEFT, reach - fm.stringWidth(label) / 2.0));
				ProgressRing.drawShadowed(g, label, lx, h - 6, Theme.TEAL);
			}
		}

		// The start: where the player stands today.
		g.setColor(Theme.INK_DEEP);
		g.fill(new Ellipse2D.Double(xs[0] - 5, ys[0] - 5, 10, 10));
		g.setColor(Theme.GOLD);
		g.setStroke(new BasicStroke(1.6f));
		g.draw(new Ellipse2D.Double(xs[0] - 4, ys[0] - 4, 8, 8));

		for (int i = 0; i < n; i++)
		{
			drawNode(g, xs[i + 1], ys[i + 1], i, path.get(i).isAffordable());
		}

		g.setClip(null);
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		boolean coinsLabel = map.getCoins() > 0 && map.getCoins() < total;
		if (!coinsLabel || reach > PAD_LEFT + 90)
		{
			ProgressRing.drawShadowed(g, Format.dps(now) + " now", PAD_LEFT + 2, h - 6, Theme.TEXT_MUTED);
		}
		String top = n == 0 ? "Nothing left to buy" : Format.dps(end) + " DPS  ·  " + Format.coins(total);
		ProgressRing.drawShadowed(g, top, w - PAD_RIGHT - fm.stringWidth(top), 15, n == 0 ? Theme.TEXT_MUTED : Theme.GOLD_BRIGHT);
		ProgressRing.drawShadowed(g, "THE ROAD AHEAD", PAD_LEFT + 2, 15, Theme.GOLD);
		g.dispose();
	}

	private void drawNode(Graphics2D g, double cx, double cy, int index, boolean affordable)
	{
		float r = NODE / 2f;
		boolean lit = hover == index;
		Color rim = affordable ? Theme.GOLD : Theme.STROKE;
		g.setColor(Theme.alpha(Theme.INK_DEEP, 235));
		g.fill(new Ellipse2D.Double(cx - r, cy - r, NODE, NODE));
		if (affordable || lit)
		{
			g.setColor(Theme.alpha(lit ? Theme.GOLD_BRIGHT : Theme.GOLD, lit ? 70 : 38));
			g.fill(new Ellipse2D.Double(cx - r - 3, cy - r - 3, NODE + 6, NODE + 6));
		}
		g.setStroke(new BasicStroke(1.4f));
		g.setColor(lit ? Theme.GOLD_BRIGHT : rim);
		g.draw(new Ellipse2D.Double(cx - r, cy - r, NODE, NODE));
		BufferedImage image = icons.get(index);
		if (image != null)
		{
			double scale = Math.min((NODE - 4) / (double) Math.max(1, image.getWidth()), (NODE - 4) / (double) Math.max(1, image.getHeight()));
			int dw = (int) Math.round(image.getWidth() * scale);
			int dh = (int) Math.round(image.getHeight() * scale);
			Composite old = g.getComposite();
			if (!affordable && !lit)
			{
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.6f));
			}
			g.drawImage(image, (int) Math.round(cx - dw / 2.0), (int) Math.round(cy - dh / 2.0), dw, dh, null);
			g.setComposite(old);
		}
		// The step number sits on the node's shoulder.
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		String label = String.valueOf(index + 1);
		float bx = (float) (cx + r - 4);
		float by = (float) (cy - r - 3);
		g.setColor(Theme.INK_DEEP);
		g.fill(new Ellipse2D.Float(bx - 5, by - 5, 10, 10));
		g.setColor(affordable ? Theme.GOLD : Theme.TEXT_FAINT);
		g.draw(new Ellipse2D.Float(bx - 5, by - 5, 10, 10));
		ProgressRing.drawShadowed(g, label, Math.round(bx - fm.stringWidth(label) / 2f), Math.round(by + fm.getAscent() / 2f - 1),
			affordable ? Theme.GOLD_BRIGHT : Theme.TEXT_MUTED);
	}

	/** A gently curving road through the waypoints. */
	private static Path2D smooth(double[] xs, double[] ys)
	{
		Path2D path = new Path2D.Double();
		path.moveTo(xs[0], ys[0]);
		for (int i = 1; i < xs.length; i++)
		{
			double mid = (xs[i - 1] + xs[i]) / 2;
			path.curveTo(mid, ys[i - 1], mid, ys[i], xs[i], ys[i]);
		}
		return path;
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Report;
import com.codex.gearroadmap.core.Result;
import com.codex.gearroadmap.core.Roadmap;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.util.function.Consumer;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** The Roadmap tab: the target, the road chart, the steps in order, then free, locked and big upgrades. */
final class RoadmapView
{
	private RoadmapView()
	{
	}

	static StackPanel build(Report report, ItemIcons icons, Runnable openTargets, Consumer<Roadmap.Option> preview)
	{
		StackPanel stack = new StackPanel(5, 8);
		Roadmap map = report.getRoadmap();
		if (!report.isLoggedIn())
		{
			stack.add(Rows.note("Log in to see the gear upgrades that will speed up your kills the most for every coin.", 190));
			return stack;
		}
		if (map == null)
		{
			stack.add(Rows.note("Reading your gear...", 190));
			return stack;
		}
		stack.add(targetCard(report, openTargets));
		if (!report.isBankSeen())
		{
			stack.add(Rows.reason(com.codex.gearroadmap.ui.Mark.Kind.NOTE,
				"Open your bank once so the roadmap knows all the gear you own, not just what you carry."));
		}
		stack.add(new RoadChart(map, icons));

		Result.Kind kind = map.getNow().best().getResult().getKind();
		if (map.getPath().isEmpty())
		{
			stack.add(Rows.note("Nothing on the Grand Exchange would make you faster here. You have the best gear for this target.", 190));
		}
		else
		{
			stack.add(new SectionHeader("Next upgrades", "most DPS per coin"));
			int rank = 0;
			for (Roadmap.Step step : map.getPath())
			{
				Roadmap.Option o = step.getOption();
				rank++;
				stack.add(UpgradeRow.build(o, UpgradeRow.Mode.STEP, rank, step.isAffordable(), kind, icons, () -> preview.accept(o)));
				kind = o.getAfter().getResult().getKind();
			}
		}
		Result.Kind now = map.getNow().best().getResult().getKind();
		if (!map.getFree().isEmpty())
		{
			stack.add(new SectionHeader("Free upgrades", "earned, not bought"));
			for (Roadmap.Option o : map.getFree())
			{
				stack.add(UpgradeRow.build(o, UpgradeRow.Mode.FREE, 0, true, now, icons, () -> preview.accept(o)));
			}
		}
		if (!map.getLeaps().isEmpty())
		{
			stack.add(new SectionHeader("Big leaps", "most DPS"));
			for (Roadmap.Option o : map.getLeaps())
			{
				stack.add(UpgradeRow.build(o, UpgradeRow.Mode.LEAP, 0, o.getCost() <= map.getCoins(), now, icons, () -> preview.accept(o)));
			}
		}
		if (!map.getLocked().isEmpty())
		{
			stack.add(new SectionHeader("Unlock by training"));
			for (Roadmap.Option o : map.getLocked())
			{
				stack.add(UpgradeRow.build(o, UpgradeRow.Mode.LOCKED, 0, false, now, icons, () -> preview.accept(o)));
			}
		}
		stack.add(Rows.note(footnote(report), 190));
		return stack;
	}

	/** What the numbers assume, in a sentence or three. */
	static String footnote(Report report)
	{
		StringBuilder text = new StringBuilder();
		if (report.isIronman())
		{
			text.append("As an ironman you cannot buy, so Grand Exchange prices here stand for how hard each item is to get. ");
		}
		else if (report.isSeasonal())
		{
			text.append("Prices are from the main game's Grand Exchange, not this world's. ");
		}
		else
		{
			text.append("Prices are live Grand Exchange prices. ");
		}
		text.append("Ammunition is priced per 1,000. Assumes ")
			.append(report.getBoosts() == null ? "no boosts" : report.getBoosts().toLowerCase())
			.append(" and your best unlocked prayers.");
		Boolean slayer = report.getSlayer();
		if (slayer != null)
		{
			String name = report.getRoadmap() == null ? "this target" : report.getRoadmap().getTarget().getName();
			text.append(slayer ? " Counts the slayer helmet bonus against " + name + "."
				: " No slayer helmet bonus against " + name + " without a task for it.");
		}
		return text.toString();
	}

	private static Card targetCard(Report report, Runnable openTargets)
	{
		Roadmap map = report.getRoadmap();
		Result r = map.getNow().best().getResult();
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(7, 10, 7, 10));
		card.accent(Theme.kind(r.getKind()));
		// The name shares its line with the button; the fight's numbers get the full width below.
		JPanel top = new JPanel(new BorderLayout(6, 0));
		top.setOpaque(false);
		JLabel name = Ui.label(map.getTarget().getName(), Theme.title(), Theme.GOLD_BRIGHT);
		name.setMinimumSize(new Dimension(10, 10));
		name.setPreferredSize(new Dimension(10, name.getPreferredSize().height));
		top.add(name, BorderLayout.CENTER);
		top.add(new CodexButton("Change", false, openTargets), BorderLayout.EAST);
		card.add(top, BorderLayout.NORTH);
		String line = r.getKind() == null ? "No way to hurt it yet"
			: r.getKind() + "  ·  max hit " + r.getMaxHit() + "  ·  " + Format.percent(r.getAccuracy()) + " acc";
		JLabel sub = Ui.label(line, Theme.small(), Theme.TEXT_MUTED);
		sub.setBorder(new EmptyBorder(3, 0, 0, 0));
		sub.setToolTipText(r.getKind() == null ? null : "Your best setup hits up to " + r.getMaxHit() + " and lands "
			+ Format.percent(r.getAccuracy()) + " of its attacks");
		card.add(sub, BorderLayout.SOUTH);
		return card;
	}
}

package com.codex.gearroadmap.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** Compact card lines: a verdict mark, a name, a quiet second line and an optional value. */
public final class Rows
{
	private Rows()
	{
	}

	public static Card check(Mark.Kind kind, String title, String detail, String value)
	{
		return line(new Mark(kind, 14), title, detail, value == null ? null : Ui.label(value, Theme.small(), Mark.color(kind)),
			kind == Mark.Kind.BAD ? Theme.BLOOD : null);
	}

	/** A verdict with a sentence that may run to two lines. */
	public static Card reason(Mark.Kind kind, String text)
	{
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(6, 8, 6, 8));
		if (kind == Mark.Kind.BAD)
		{
			card.accent(Theme.BLOOD);
		}
		JPanel holder = new JPanel(new BorderLayout());
		holder.setOpaque(false);
		holder.setBorder(new EmptyBorder(1, 0, 0, 0));
		holder.add(new Mark(kind, 14), BorderLayout.NORTH);
		card.add(holder, BorderLayout.WEST);
		card.add(Ui.wrapped(text, Theme.body(), Theme.TEXT, 160), BorderLayout.CENTER);
		return card;
	}

	public static Card line(JComponent lead, String title, String detail, JComponent trailing, Color accent)
	{
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(6, 8, 6, 8));
		if (accent != null)
		{
			card.accent(accent);
		}
		if (lead != null)
		{
			JPanel holder = new JPanel(new BorderLayout());
			holder.setOpaque(false);
			holder.setBorder(new EmptyBorder(1, 0, 0, 0));
			holder.add(lead, BorderLayout.NORTH);
			card.add(holder, BorderLayout.WEST);
		}
		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		JLabel name = Ui.label(title, Theme.body(), Theme.TEXT);
		name.setToolTipText(title);
		text.add(name);
		if (detail != null && !detail.isEmpty())
		{
			JLabel sub = Ui.label(detail, Theme.small(), Theme.TEXT_MUTED);
			sub.setToolTipText(detail);
			text.add(sub);
		}
		// Long names clip with an ellipsis rather than push the value off the card.
		text.setMinimumSize(new Dimension(10, 10));
		text.setPreferredSize(new Dimension(10, text.getPreferredSize().height));
		card.add(text, BorderLayout.CENTER);
		if (trailing != null)
		{
			JPanel holder = new JPanel(new BorderLayout());
			holder.setOpaque(false);
			holder.add(trailing, BorderLayout.NORTH);
			card.add(holder, BorderLayout.EAST);
		}
		return card;
	}

	/** A quiet line of text for empty states. */
	public static JComponent note(String text, int width)
	{
		JPanel holder = new JPanel(new BorderLayout());
		holder.setOpaque(false);
		holder.setBorder(new EmptyBorder(2, 4, 2, 4));
		holder.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_FAINT, width), BorderLayout.CENTER);
		return holder;
	}
}

package com.codex.gearroadmap.ui;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.util.function.Consumer;
import javax.swing.JTextField;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

/** An inked search line with a small lens, matching the rest of the panel. */
class SearchField extends JTextField
{
	private final String hint;

	SearchField(String hint, Consumer<String> onChange)
	{
		this.hint = hint;
		setOpaque(false);
		setFont(Theme.body());
		setForeground(Theme.TEXT);
		setCaretColor(Theme.GOLD_BRIGHT);
		setSelectionColor(Theme.alpha(Theme.GOLD, 90));
		setBorder(new EmptyBorder(4, 24, 4, 8));
		setPreferredSize(new Dimension(10, 26));
		getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				onChange.accept(getText());
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				onChange.accept(getText());
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				onChange.accept(getText());
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(shape);
		g.setColor(isFocusOwner() ? Theme.alpha(Theme.GOLD, 150) : Theme.STROKE_SOFT);
		g.draw(shape);
		g.setStroke(new BasicStroke(1.4f));
		g.setColor(Theme.GOLD_DIM);
		g.draw(new Ellipse2D.Float(8, h / 2f - 5, 8, 8));
		g.drawLine(15, h / 2 + 2, 18, h / 2 + 5);
		if (getText().isEmpty() && !isFocusOwner())
		{
			g.setFont(getFont());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(hint, 24, (h + g.getFontMetrics().getAscent()) / 2 - 2);
		}
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int h = getHeight();
		int mid = h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(4, mid - 4);
		diamond.lineTo(8, mid);
		diamond.lineTo(4, mid + 4);
		diamond.lineTo(0, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		int textX = 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = getWidth();
		if (trailing != null)
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = getWidth() - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, getWidth() - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
		g.dispose();
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			ProgressRing.drawShadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

package com.codex.gearroadmap.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/** Gear Roadmap's mark: a gilt signpost over a winding road with a teal waypoint at its end. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;

		// The road, winding up from the bottom left.
		Path2D road = new Path2D.Float();
		road.moveTo(x + 1 * s, y + 15.5f * s);
		road.curveTo(x + 6 * s, y + 14 * s, x + 2 * s, y + 10.5f * s, x + 7 * s, y + 10 * s);
		road.curveTo(x + 11 * s, y + 9.6f * s, x + 10 * s, y + 7.4f * s, x + 13.5f * s, y + 6.6f * s);
		g.setStroke(new BasicStroke(Math.max(1.6f, 2.2f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
		g.draw(road);
		g.setStroke(new BasicStroke(Math.max(1f, 1.3f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setPaint(new GradientPaint(x, y + 16 * s, Theme.GOLD_DIM, x + 14 * s, y + 6 * s, Theme.GOLD_BRIGHT));
		g.draw(road);

		// The post and its two boards.
		g.setStroke(new BasicStroke(Math.max(1f, 1.1f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.GOLD);
		g.drawLine(Math.round(x + 4.5f * s), Math.round(y + 2 * s), Math.round(x + 4.5f * s), Math.round(y + 11.5f * s));
		Path2D board = new Path2D.Float();
		board.moveTo(x + 4.5f * s, y + 2.2f * s);
		board.lineTo(x + 9.4f * s, y + 2.2f * s);
		board.lineTo(x + 10.8f * s, y + 3.4f * s);
		board.lineTo(x + 9.4f * s, y + 4.6f * s);
		board.lineTo(x + 4.5f * s, y + 4.6f * s);
		board.closePath();
		Path2D back = new Path2D.Float();
		back.moveTo(x + 4.5f * s, y + 5.6f * s);
		back.lineTo(x + 1.6f * s, y + 5.6f * s);
		back.lineTo(x + 0.5f * s, y + 6.7f * s);
		back.lineTo(x + 1.6f * s, y + 7.8f * s);
		back.lineTo(x + 4.5f * s, y + 7.8f * s);
		back.closePath();
		g.setPaint(new GradientPaint(x, y + 2 * s, Theme.GOLD_BRIGHT, x, y + 8 * s, Theme.GOLD_DIM));
		g.fill(board);
		g.fill(back);
		g.setColor(Theme.INK_DEEP);
		g.setStroke(new BasicStroke(Math.max(0.7f, 0.6f * s)));
		g.draw(board);
		g.draw(back);

		// The waypoint the road leads to.
		float r = 1.9f * s;
		g.setColor(Theme.alpha(Theme.TEAL, 90));
		g.fill(new Ellipse2D.Float(x + 13.5f * s - r * 1.6f, y + 6.6f * s - r * 1.6f, r * 3.2f, r * 3.2f));
		g.setColor(Theme.TEAL);
		g.fill(new Ellipse2D.Float(x + 13.5f * s - r, y + 6.6f * s - r, r * 2, r * 2));
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(Theme.RADIUS, 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(), 8, 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		ProgressRing.drawShadowed(g, value, 8, 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null)
		{
			g.setFont(Theme.small());
			String clipped = note;
			while (clipped.length() > 1 && small.stringWidth(clipped) > w - 16)
			{
				clipped = clipped.substring(0, clipped.length() - 2) + "…";
			}
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(clipped, 8, h - 6);
		}
		g.dispose();
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Report;
import com.codex.gearroadmap.core.Result;
import com.codex.gearroadmap.core.Roadmap;
import com.codex.gearroadmap.data.Target;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.util.Locale;
import java.util.function.Consumer;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** The Targets tab: every target with the best the player can do there now; clicking one aims the roadmap at it. */
final class TargetsView
{
	static final String[] FILTERS = {"All", "Bosses", "Slayer", "Training"};

	private TargetsView()
	{
	}

	static StackPanel build(Report report, int filter, String search, String focused, Consumer<String> onPick)
	{
		StackPanel stack = new StackPanel(4, 8);
		if (!report.isLoggedIn())
		{
			stack.add(Rows.note("Log in to compare your gear against every target.", 190));
			return stack;
		}
		if (report.getSurvey().isEmpty())
		{
			stack.add(Rows.note("Weighing your gear against every target...", 190));
			return stack;
		}
		String needle = search == null ? "" : search.trim().toLowerCase(Locale.ROOT);
		int shown = 0;
		for (Roadmap.Survey row : report.getSurvey())
		{
			Target t = row.getTarget();
			if (!matches(t, filter) || !needle.isEmpty() && !t.getName().toLowerCase(Locale.ROOT).contains(needle))
			{
				continue;
			}
			stack.add(row(row, t.getName().equals(focused), onPick));
			shown++;
		}
		if (shown == 0)
		{
			stack.add(Rows.note("No targets match.", 190));
		}
		return stack;
	}

	private static boolean matches(Target t, int filter)
	{
		switch (filter)
		{
			case 1:
				return "Boss".equals(t.getGroup());
			case 2:
				return "Slayer".equals(t.getGroup());
			case 3:
				return "Training".equals(t.getGroup());
			default:
				return true;
		}
	}

	private static Card row(Roadmap.Survey row, boolean focused, Consumer<String> onPick)
	{
		Target t = row.getTarget();
		Result r = row.getPlan().getResult();
		Card card = new Card(new BorderLayout(8, 0));
		card.setBorder(new EmptyBorder(5, 10, 5, 10));
		card.accent(Theme.kind(r.getKind()));
		card.highlighted(focused);

		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.add(Ui.label(t.getName(), Theme.body(), focused ? Theme.GOLD_BRIGHT : Theme.TEXT));
		String line = r.getKind() == null ? "Out of reach" : Format.dps(r.getDps()) + " DPS  ·  " + r.getKind();
		text.add(Ui.label(line, Theme.small(), r.getKind() == null ? Theme.TEXT_FAINT : Theme.mix(Theme.TEXT_MUTED, Theme.kind(r.getKind()), 0.5)));
		text.setMinimumSize(new Dimension(10, 10));
		text.setPreferredSize(new Dimension(10, text.getPreferredSize().height));
		card.add(text, BorderLayout.CENTER);

		JPanel trail = new JPanel();
		trail.setOpaque(false);
		trail.setLayout(new BoxLayout(trail, BoxLayout.Y_AXIS));
		JLabel time = Ui.label(Format.time(r.secondsToKill(t)), Theme.body(), Theme.TEXT);
		time.setAlignmentX(JComponent.RIGHT_ALIGNMENT);
		trail.add(time);
		JLabel caption = Ui.label(focused ? "aimed" : "per kill", Theme.small(), focused ? Theme.GOLD : Theme.TEXT_FAINT);
		caption.setAlignmentX(JComponent.RIGHT_ALIGNMENT);
		trail.add(caption);
		card.add(trail, BorderLayout.EAST);
		card.setToolTipText("<html><b>" + Ui.escape(t.getName()) + "</b><br>" + t.getHp() + " hitpoints, " + t.getDefence()
			+ " Defence<br>Click to aim your roadmap here</html>");
		card.onClick(() -> onPick.accept(t.getName()));
		return card;
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Result;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * Gear Roadmap gives each kind of attack its own colour: ember for melee, green for
 * ranged and violet for magic.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** The colour of a kind of attack. */
	public static Color kind(Result.Kind kind)
	{
		if (kind == null)
		{
			return TEXT_MUTED;
		}
		switch (kind)
		{
			case MELEE:
				return EMBER;
			case RANGED:
				return GREEN;
			default:
				return VIOLET;
		}
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.gearroadmap.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}
}

package com.codex.gearroadmap.ui;

import com.codex.gearroadmap.core.Result;
import com.codex.gearroadmap.core.Roadmap;
